INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE', 'english', 9, 'Use euphemisms to show politeness', ARRAY['ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.a', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.b']::text[], 'The child replaces blunt words with polite ones where tact is needed (passed away for died, senior citizen for old person, washroom for toilet, between jobs for jobless) and knows what each means. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the polite expression","replace the blunt word","what does this euphemism mean"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE', 'english', 9, 'Conduct a debate while keeping the conventions of polite language', ARRAY['ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.c']::text[], 'The child addresses the chair and the house, states the side, argues with reasons and examples, rebuts the other side''s points politely (My opponent claims ..., but ...), and keeps to time. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["take part in a class debate","propose or oppose the motion","rebut a point politely"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_', 'english', 9, 'Select and read grade-appropriate texts and keep a reading log or portfolio', ARRAY['ENGL.G9.READIN.T1_INDEPENDENT_READING_.a', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_.b', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_.c', 'ENGL.G9.READIN.T9_EXTENSIVE_READING_GR.a', 'ENGL.G9.READIN.T9_EXTENSIVE_READING_GR.b', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.b', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.c']::text[], 'The child selects fiction and non-fiction from digital and print sources, reads widely across the term, and keeps a reading log or portfolio noting what each text was about and what he or she thought of it. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["reading log","portfolio of subject matter","recommend a book"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.GENDER_NEUTRAL', 'ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU', 'english', 9, 'Replace gender-biased words with gender-neutral ones', ARRAY['ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.a', 'ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.b']::text[], 'The child spots gender-biased words (chairman, policeman, fireman, waitress, mankind) and picks neutral ones (chairperson, police officer, firefighter, server, humankind), and says a job word should not assume the sex of the worker. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S.PL_STRUCTURE', 'ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S', 'english', 9, 'Describe the setting and the order of a play', ARRAY['ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S.a', 'ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S.b']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN.LEGIBILITY', 'ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN', 'english', 9, 'Indent paragraphs, break words correctly and write a neat, legible text', ARRAY['ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN.a', 'ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN.b', 'ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN.c']::text[], 'The child indents every paragraph, breaks a word at a line end only between syllables with a hyphen (envir-onment, not en-vironment), and writes a neat, legible page. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["write a fair copy","break the word at the line end","indent each paragraph"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.SHORT_FORMS', 'ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR', 'english', 9, 'Identify and explain riddles, tongue twisters and proverbs', ARRAY['ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.a', 'ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.b']::text[], 'The child tells a riddle (a puzzle with a hidden answer, often with a fixed opening), a tongue twister (repeated similar sounds to practise speech) and a proverb (a short saying with a lesson) apart, and says what each is used for. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["riddle, tongue twister or proverb","what is it for","what is the answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.PERFORM_ORAL', 'ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR', 'english', 9, 'Perform short oral forms, oral poems and parts of a play', ARRAY['ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.c', 'ENGL.G9.LISTEN.T8_ORAL_POETRY.b', 'ENGL.G9.READIN.T10_PLAY_PROJECT.b', 'ENGL.G9.READIN.T13_GRADE_APPROPRIATE_PL.b', 'ENGL.G9.READIN.T14_INTENSIVE_READING_PL.d']::text[], 'The child performs riddles, tongue twisters, oral poems and play scenes with clear diction, fitting voice, gestures, facial expression, props where needed and audience involvement. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["perform the riddles","recite the oral poem","act the scene"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_SI.RP_STYLE', 'ENGL.G9.READIN.T2_INTENSIVE_READING_SI', 'english', 9, 'Name repetition and its function in a poem', ARRAY['ENGL.G9.READIN.T2_INTENSIVE_READING_SI.a', 'ENGL.G9.READIN.T2_INTENSIVE_READING_SI.b']::text[], 'The child reads the poem for its speaker, repetition and message and picks the one that fits all its lines, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS', 'ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER', 'english', 9, 'Use quantifiers with count and non-count nouns', ARRAY['ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.a', 'ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.b']::text[], 'The child uses many, few and a number of with count nouns, much and little with non-count nouns, and some, a lot of and plenty of with both; he sorts nouns (books, chairs: count; water, advice: non-count). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE', 'ENGL.G9.READIN.T2_INTENSIVE_READING_PL', 'english', 9, 'Describe the sequence of events in a play and relate them to life', ARRAY['ENGL.G9.READIN.T2_INTENSIVE_READING_PL.a', 'ENGL.G9.READIN.T2_INTENSIVE_READING_PL.b']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS', 'ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING', 'english', 9, 'Use double quotation marks and brackets', ARRAY['ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.a', 'ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.b']::text[], 'The child puts the exact words spoken inside double quotation marks, and puts extra information or an explanation inside brackets, and does not use brackets for speech. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T3_LISTENING_COMPREHENS.LS_MAIN', 'ENGL.G9.LISTEN.T3_LISTENING_COMPREHENS', 'english', 9, 'Pick the main idea and specific details of an argumentative listening text', ARRAY['ENGL.G9.LISTEN.T3_LISTENING_COMPREHENS.a', 'ENGL.G9.LISTEN.T3_LISTENING_COMPREHENS.b', 'ENGL.G9.LISTEN.T7_LISTENING_COMPREHENS.a']::text[], 'The child remembers what was said and picks the answer that fits the whole talk, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T3_READING_FOR_INFORMAT.RS_CONTEXT', 'ENGL.G9.READIN.T3_READING_FOR_INFORMAT', 'english', 9, 'Infer the meaning of words and sentences from the context', ARRAY['ENGL.G9.READIN.T3_READING_FOR_INFORMAT.a']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T3_READING_FOR_INFORMAT.RS_CONNECT', 'ENGL.G9.READIN.T3_READING_FOR_INFORMAT', 'english', 9, 'Connect events in a text to real life', ARRAY['ENGL.G9.READIN.T3_READING_FOR_INFORMAT.b']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS', 'ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES', 'english', 9, 'Use modal auxiliaries to show ability, permission, possibility and duty', ARRAY['ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.a', 'ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.b']::text[], 'The child says can and could show ability, may and might permission or possibility, must and should duty or advice, and that a modal is followed by the base verb. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE', 'english', 9, 'Describe the structure of a poem and personification', ARRAY['ENGL.G9.READIN.T3_POEMS_STRUCTURE.a', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.b']::text[], 'The child says a poem is made of lines grouped in stanzas, that rhyme is repeated end sounds, and that personification gives human actions or feelings to a thing, as in "the wind whispered". Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE', 'english', 9, 'Create a poem on a topic of interest', ARRAY['ENGL.G9.READIN.T3_POEMS_STRUCTURE.c']::text[], 'The child writes a short poem in stanzas on a topic (environmental conservation), with imagery, a device such as personification or repetition, and a clear feeling or message. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a poem about","add a stanza","use personification"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG', 'english', 9, 'Name the characteristics of a well-formed paragraph', ARRAY['ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.a']::text[], 'The child says a good paragraph has a topic sentence, supporting sentences, unity (one idea), coherence (ideas in order, joined by linking words) and a closing sentence. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG', 'english', 9, 'Write well-developed, coherent, unified narrative and descriptive paragraphs', ARRAY['ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.b', 'ENGL.G9.WRITIN.T4_NARRATIVE_AND_DESCRI.a', 'ENGL.G9.WRITIN.T4_NARRATIVE_AND_DESCRI.b', 'ENGL.G9.WRITIN.T4_NARRATIVE_AND_DESCRI.c']::text[], 'The child writes paragraphs with a topic sentence, unity (one idea), coherence (linked in order), development (examples or details) and a close, using the first or second person as asked. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a paragraph about","write a narrative paragraph in the first person","write a descriptive paragraph"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND', 'ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING', 'english', 9, 'Select information from listening texts and judge and respond to their message', ARRAY['ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.a', 'ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.b', 'ENGL.G9.LISTEN.T7_LISTENING_COMPREHENS.b', 'ENGL.G9.LISTEN.T13_EXTENSIVE_LISTENING_.a', 'ENGL.G9.LISTEN.T13_EXTENSIVE_LISTENING_.b', 'ENGL.G9.LISTEN.T12_LISTENING_TO_RESPOND.a', 'ENGL.G9.LISTEN.T12_LISTENING_TO_RESPOND.b', 'ENGL.G9.LISTEN.T8_ORAL_POETRY.a']::text[], 'The child selects the information asked for from a listening text, takes notes on points made by different speakers, judges the message with a reason, and responds, including expressing feelings about a poem with fitting words. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["what information did you hear","is the message fair","take notes on the speeches"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT', 'ENGL.G9.READIN.T4_INTENSIVE_READING', 'english', 9, 'Predict events in a reading text', ARRAY['ENGL.G9.READIN.T4_INTENSIVE_READING.a']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_KEYEVENTS', 'ENGL.G9.READIN.T4_INTENSIVE_READING', 'english', 9, 'Outline the key events in a text', ARRAY['ENGL.G9.READIN.T4_INTENSIVE_READING.b']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_QUESTIONS', 'ENGL.G9.READIN.T4_INTENSIVE_READING', 'english', 9, 'Answer direct and inferential questions and use clues for word meaning', ARRAY['ENGL.G9.READIN.T4_INTENSIVE_READING.c', 'ENGL.G9.READIN.T4_INTENSIVE_READING.d']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_RELATE', 'ENGL.G9.READIN.T4_INTENSIVE_READING', 'english', 9, 'Relate the characters, events and places in a text to real life', ARRAY['ENGL.G9.READIN.T4_INTENSIVE_READING.e', 'ENGL.G9.READIN.T14_INTENSIVE_READING_PL.c', 'ENGL.G9.READIN.T15_INTENSIVE_READING_PO.a', 'ENGL.G9.READIN.T15_INTENSIVE_READING_PO.b']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT', 'ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER', 'english', 9, 'Tell the present perfect from the past perfect', ARRAY['ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.a', 'ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.b']::text[], 'The child says the present perfect is have or has plus the past participle (She has finished) and the past perfect is had plus the past participle (She had finished before I came). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_.PL_CHARACTERS', 'ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_', 'english', 9, 'Identify the characters in a play and describe their actions with adverbs', ARRAY['ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_.a', 'ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_.c', 'ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_.b', 'ENGL.G9.READIN.T14_INTENSIVE_READING_PL.a']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'ENGL.G9.LISTEN.T5_PRONUNCIATION', 'english', 9, 'Pronounce semi-vowels and diphthongs with clarity', ARRAY['ENGL.G9.LISTEN.T5_PRONUNCIATION.a', 'ENGL.G9.LISTEN.T9_DIPHTHONGS_AND_SENTE.a']::text[], 'The child identifies and says /j/ (yes), /w/ (wet) and the diphthongs /aɪ/ (my), /eɪ/ (day), /aʊ/ (now) and /ʊə/ (tour) clearly, so that yet and wet, day and die are heard correctly. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","which word has the sound","read the sentence aloud"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS', 'ENGL.G9.LISTEN.T5_PRONUNCIATION', 'english', 9, 'Stress content words and use emphatic stress to convey meaning', ARRAY['ENGL.G9.LISTEN.T5_PRONUNCIATION.b', 'ENGL.G9.LISTEN.T9_DIPHTHONGS_AND_SENTE.b']::text[], 'The child stresses content words and keeps function words weak, and moves the stress to the word that carries the contrast (SHE won the medal, not her brother). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["stress the content words","stress the word that changes the meaning","say it to mean something else"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_', 'english', 9, 'Use the dictionary, thesaurus and encyclopaedia to research a topic', ARRAY['ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.a', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.b', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.c']::text[], 'The child names the main reference materials and what each is for, checks a word''s meaning, part of speech and usage in a dictionary, finds synonyms in a thesaurus, and uses an encyclopaedia for a short research task. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which reference would you use","check the usage","research the topic"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER', 'ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES', 'english', 9, 'Put adjectives in the correct order', ARRAY['ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.a', 'ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.b']::text[], 'The child says adjectives go in the order opinion, size, age, colour, origin, material, so we say "a lovely small old brown wooden box". Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE', 'ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA', 'english', 9, 'Identify features of style in a play and relate them to its message', ARRAY['ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.a', 'ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.b', 'ENGL.G9.READIN.T9_PLAY_STYLE_CLASS_REA.a', 'ENGL.G9.READIN.T9_PLAY_STYLE_CLASS_REA.b', 'ENGL.G9.READIN.T13_GRADE_APPROPRIATE_PL.a']::text[], 'The child finds features of style in a play (dialogue, irony, humour, monologue, songs, stage directions, flashback) with examples and explains how each supports the play''s message. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["find an example of","what does this device show","how does it support the message"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO', 'english', 9, 'Name the parts of a letter of application', ARRAY['ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.a']::text[], 'The child names the writer''s address, date, receiver''s address, salutation (Dear Sir or Madam), subject line, body, subscription (Yours faithfully) and signature, and says Yours faithfully goes with Dear Sir or Madam. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO', 'english', 9, 'Write a letter of application for placement at Senior School', ARRAY['ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.b']::text[], 'The child writes a formal letter with both addresses, the date, Dear Sir or Madam, a subject line, the purpose, his or her qualifications and interests, a polite request, Yours faithfully, signature and full name. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a letter of application","correct this letter","what is missing"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION', 'ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL', 'english', 9, 'Use words, phrases and cues for negotiation', ARRAY['ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.a', 'ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.b']::text[], 'The child uses negotiating phrases (Would you consider ...? How about we meet halfway? I can offer ... if you ...), listens to the other side, offers a compromise and uses calm cues (eye contact, open hands). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the negotiating phrase","make a counter-offer","which response keeps the deal going"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'ENGL.G9.READIN.T6_READING_FLUENCY', 'english', 9, 'Read at the right speed, accurately and with expression', ARRAY['ENGL.G9.READIN.T6_READING_FLUENCY.a', 'ENGL.G9.READIN.T6_READING_FLUENCY.b']::text[], 'The child names ways of reading more fluently (preview, read in phrases, ignore an unknown word and read on, vary the voice) and reads a Grade 9 text accurately and expressively at the right speed. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","ways to read more fluently","read the scene with expression"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES', 'ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB', 'english', 9, 'Use the degrees of comparison of adverbs', ARRAY['ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.a', 'ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.b']::text[], 'The child says the positive (fast), comparative (faster, more carefully) and superlative (fastest, most carefully) and that long adverbs take more and most. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL', 'english', 9, 'Identify and analyse the themes in a play', ARRAY['ENGL.G9.READIN.T6_INTENSIVE_READING_PL.a', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL.b', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL.c', 'ENGL.G9.READIN.T14_INTENSIVE_READING_PL.b']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING', 'english', 9, 'Tell homophones and homonyms and spell commonly misspelt words', ARRAY['ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.a', 'ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.b', 'ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.a']::text[], 'The child says homophones sound alike but differ in spelling and meaning (their and there), homonyms share spelling and sound (bank), and spells words such as separate, necessary, beginning and committee. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN', 'english', 9, 'Distinguish reading for interpretation from reading for evaluation, and interpret a text', ARRAY['ENGL.G9.READIN.T7_INTENSIVE_READING_IN.a', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN.b']::text[], 'The child explains what a text means (interpretation) and separately judges how true, fair or useful it is (evaluation), giving reasons from the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does the writer mean","is the claim reliable","interpretation or evaluation"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS', 'ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN', 'english', 9, 'Use relative and interrogative pronouns', ARRAY['ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.a', 'ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.b']::text[], 'The child says who and whom refer to people, which to things and animals, whose to belonging, that to people or things, and that who, what, which and whose also start questions. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_PL.PL_RELATIONSHIP', 'ENGL.G9.READIN.T7_INTENSIVE_READING_PL', 'english', 9, 'Analyse the characters in a play and their relationship', ARRAY['ENGL.G9.READIN.T7_INTENSIVE_READING_PL.a', 'ENGL.G9.READIN.T7_INTENSIVE_READING_PL.b']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS', 'english', 9, 'Outline the stages of the writing process', ARRAY['ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.a', 'ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.a']::text[], 'The child names and orders the stages (prewriting, drafting, revising, editing, publishing) and says what happens at each, including for a dialogue. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the stages","what happens at this stage","which stage is this"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS', 'english', 9, 'Write compositions, stories and poems through the writing process, using narrative elements and idioms', ARRAY['ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.b', 'ENGL.G9.WRITIN.T8_ASSESSING_WRITING.b', 'ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.b', 'ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.b']::text[], 'The child writes a story with setting, characters, a plot that builds to a climax and a resolution, background details that make it believable and idioms that fit, following the writing process. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a story about","use the elements of a narrative","use idioms in your story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV', 'ENGL.G9.READIN.T8_READING_FOR_INTERPRE', 'english', 9, 'Identify the point of view of a poem', ARRAY['ENGL.G9.READIN.T8_READING_FOR_INTERPRE.a', 'ENGL.G9.READIN.T8_READING_FOR_INTERPRE.b']::text[], 'The child reads the poem for its speaker, repetition and message and picks the one that fits all its lines, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS', 'ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS', 'english', 9, 'Use complex prepositions', ARRAY['ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.a', 'ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.b']::text[], 'The child names complex prepositions of two or three words (because of, in front of, instead of, in spite of, according to, on behalf of) and uses them correctly. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T8_POETRY_CHARACTERS.RP_PERSONA', 'ENGL.G9.READIN.T8_POETRY_CHARACTERS', 'english', 9, 'Identify the persona and other participants in a poem', ARRAY['ENGL.G9.READIN.T8_POETRY_CHARACTERS.a', 'ENGL.G9.READIN.T8_POETRY_CHARACTERS.b']::text[], 'The child reads the poem for its speaker, repetition and message and picks the one that fits all its lines, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T8_ASSESSING_WRITING.ASSESS_WRITING', 'ENGL.G9.WRITIN.T8_ASSESSING_WRITING', 'english', 9, 'Identify the qualities of a good composition and assess one against criteria', ARRAY['ENGL.G9.WRITIN.T8_ASSESSING_WRITING.a', 'ENGL.G9.WRITIN.T8_ASSESSING_WRITING.c']::text[], 'The child names the qualities of a good composition (relevance, organisation, language, creativity, mechanics) and scores a composition against given criteria with comments and suggested corrections. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["assess with the rubric","what makes it good","give feedback"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.CORRELATIVE', 'ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA', 'english', 9, 'Use correlative conjunctions in pairs', ARRAY['ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.a', 'ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.b']::text[], 'The child pairs either with or, neither with nor, both with and, not only with but also, and whether with or. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.NARRATIVE_ELEMENTS', 'ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO', 'english', 9, 'Name the elements of a narrative composition', ARRAY['ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.a']::text[], 'The child names characters, setting, plot (beginning, complication, climax, resolution) and theme, and says background information makes a story believable. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH', 'ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES', 'english', 9, 'Prepare quickly for and make an impromptu speech', ARRAY['ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.a', 'ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.b']::text[], 'Given a topic, the child takes a minute to choose a position and two or three points, then speaks with an opening, the points with examples and a short close, clearly and with confidence. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["speak for two minutes on a topic just given","plan in one minute","what are the steps"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING', 'ENGL.G9.READIN.T10_NOTE_MAKING', 'english', 9, 'Identify the main points of an argumentative passage and make notes', ARRAY['ENGL.G9.READIN.T10_NOTE_MAKING.a', 'ENGL.G9.READIN.T10_NOTE_MAKING.b']::text[], 'The child picks out the position, the main arguments and the evidence of an argumentative passage, and notes them in key words under headings for and against. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["make notes from the passage","list the arguments for and against","what are the main points"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM', 'ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS', 'english', 9, 'Use numerals and ordinals as determiners', ARRAY['ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.a', 'ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.b']::text[], 'The child says cardinal numbers (two, ten) count and ordinal numbers (second, tenth) give position, and both come before the noun. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES', 'ENGL.G9.READIN.T10_PLAY_PROJECT', 'english', 9, 'Identify simple props and costumes that create mood and atmosphere', ARRAY['ENGL.G9.READIN.T10_PLAY_PROJECT.a']::text[], 'The child chooses simple props and costumes for a scene (a lantern for night, a torn kanga for poverty) and says what mood or atmosphere they create. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which prop fits the scene","what mood does the costume create","choose a costume for"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS', 'ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC', 'english', 9, 'Recognise and fill bursary and scholarship application forms', ARRAY['ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.a', 'ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.b']::text[], 'The child picks out bursary and scholarship forms from others, and fills one accurately and completely, in capitals where asked, with the right documents attached and the declaration signed. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["which form is a bursary form","fill in the form","correct the form"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW', 'ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_', 'english', 9, 'Prepare for and take part in a mock job interview', ARRAY['ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.a', 'ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.b']::text[], 'The child prepares (researching the job, dressing well, bringing documents), asks or answers fitting interview questions with examples, and greets, listens and closes politely. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["prepare for the interview","ask the interviewee","answer the panel"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI', 'english', 9, 'Distinguish between fiction and non-fiction', ARRAY['ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.a']::text[], 'The child sorts texts into fiction (made-up characters and events) and non-fiction (facts about real people, places and events), giving clues from the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["fiction or non-fiction","which clues show it","sort the books"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED', 'ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS', 'english', 9, 'Form nouns from verbs and from other nouns', ARRAY['ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.a', 'ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.b']::text[], 'The child forms nouns from verbs (decide to decision, teach to teacher, move to movement) and from other nouns (child to childhood, friend to friendship). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.PL_LESSONS', 'ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL', 'english', 9, 'Identify the lessons learnt from a play', ARRAY['ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.a', 'ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.b']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.ABBREVIATIONS', 'ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING', 'english', 9, 'Write common abbreviations and acronyms in full', ARRAY['ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.b']::text[], 'The child gives the full form of common abbreviations and acronyms such as e.g. (for example), i.e. (that is), etc. (and so on), UN (United Nations), WHO (World Health Organisation) and ICT (information and communication technology). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T12_INTENSIVE_READING_CO.RS_CLUES', 'ENGL.G9.READIN.T12_INTENSIVE_READING_CO', 'english', 9, 'Find clues in a passage and infer meaning from them', ARRAY['ENGL.G9.READIN.T12_INTENSIVE_READING_CO.a', 'ENGL.G9.READIN.T12_INTENSIVE_READING_CO.b', 'ENGL.G9.READIN.T12_INTENSIVE_READING_CO.d']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T12_PHRASAL_VERBS.PHRASAL_VERBS', 'ENGL.G9.GRAMMA.T12_PHRASAL_VERBS', 'english', 9, 'Know phrasal verbs of break, hang, run and turn', ARRAY['ENGL.G9.GRAMMA.T12_PHRASAL_VERBS.a', 'ENGL.G9.GRAMMA.T12_PHRASAL_VERBS.b']::text[], 'The child knows break down (stop working), break out (start suddenly), hang on (wait), hang up (end a call), run out of (have no more), run into (meet by chance), turn up (arrive), turn down (refuse). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T12_PLAY_CHARACTERISATIO.PL_TRAITS', 'ENGL.G9.READIN.T12_PLAY_CHARACTERISATIO', 'english', 9, 'Outline clues for the traits of characters in a play', ARRAY['ENGL.G9.READIN.T12_PLAY_CHARACTERISATIO.a', 'ENGL.G9.READIN.T12_PLAY_CHARACTERISATIO.b']::text[], 'The child reads the scene and picks the answer that fits the words and stage directions, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_', 'english', 9, 'Apply the writing process in creating a dialogue', ARRAY['ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.b']::text[], 'The child plans, drafts, revises and edits a dialogue on a theme, with a setting, names and colons, a new line per speaker, stage directions in brackets and a clear purpose. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a dialogue on","revise the dialogue","set out the dialogue"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES', 'ENGL.G9.READIN.T13_INTENSIVE_READING_VI', 'english', 9, 'Pick the mental images a passage creates', ARRAY['ENGL.G9.READIN.T13_INTENSIVE_READING_VI.a']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE', 'english', 9, 'Use subordinating conjunctions in complex sentences', ARRAY['ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.a', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.b', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.c']::text[], 'The child picks because (reason), although (contrast), if and unless (condition), when and while (time) and since, and says a complex sentence has a main clause and a subordinate clause. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS', 'ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI', 'english', 9, 'Explain the meaning of idioms in different contexts', ARRAY['ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.a']::text[], 'The child explains given idioms from their context (all at sea, to rock the boat, plain sailing) and chooses the idiom that fits a situation. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does the idiom mean here","choose the idiom","use it in a sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN', 'english', 9, 'Write and use question tags with the correct intonation', ARRAY['ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.a', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.b', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.c']::text[], 'The child writes the tag with the helping verb, the opposite sign and a pronoun (You play football, don''t you?), uses will you after commands and let''s with shall we, and uses a falling tune when sure and a rising tune when asking. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["add the question tag","rise or fall","write a sentence with a tag"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT', 'english', 9, 'Pick out the main points and organise them into a summary', ARRAY['ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.a', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.b', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN.c', 'ENGL.G9.READIN.T12_INTENSIVE_READING_CO.c', 'ENGL.G9.READIN.T13_INTENSIVE_READING_VI.b', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.c']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND', 'english', 9, 'Change direct speech into indirect speech', ARRAY['ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.a', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.b', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.c', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.d']::text[], 'The child says direct speech gives the exact words in quotation marks and indirect speech reports them without quotation marks, with tense and pronouns changed (am becomes was, now becomes then). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_', 'english', 9, 'Write a descriptive composition of 280 to 320 words using the five senses', ARRAY['ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.a', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.b', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.c', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.d']::text[], 'The child follows the writing process to write a 280 to 320 word description that uses all five senses, exact and imaginative language, correct spelling and a clear order. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["describe the stadium","use all five senses","revise and spell-check"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO', 'english', 9, 'Read and analyse a news report and present one', ARRAY['ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.a', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.b', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.c']::text[], 'The child reads a short news report in the time given, with clear pace and pauses, names the features of a good oral news report (headline first, who, what, where, when, a neutral tone), and presents one. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read the news in two minutes","what makes this report good","present the news"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY', 'ENGL.G9.READIN.T15_READING_FLUENCY', 'english', 9, 'Make predictions about characters, events and the message of a text', ARRAY['ENGL.G9.READIN.T15_READING_FLUENCY.b']::text[], 'The child finds the answer in the passage and picks the one that covers what the question asks, and does not pick a small detail, the opposite or something not in the text. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer on a second text"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN', 'ENGL.G9.READIN.T15_READING_FLUENCY', 'english', 9, 'Preview, skim and scan a text', ARRAY['ENGL.G9.READIN.T15_READING_FLUENCY.a', 'ENGL.G9.READIN.T15_READING_FLUENCY.c', 'ENGL.G9.READIN.T15_READING_FLUENCY.d']::text[], 'The child previews a text and reads on past unknown words, skims for the gist (title, first lines, headings) and scans for a specific detail. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is the text about","find the date","what do you do with an unknown word"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE', 'ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI', 'english', 9, 'Punctuate imperative and exclamatory sentences', ARRAY['ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.a', 'ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.b']::text[], 'The child says an imperative gives a command or request and ends with a full stop or exclamation mark, and an exclamatory sentence shows strong feeling and ends with an exclamation mark. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G9.WRITIN.T15_EMAILS.EMAIL', 'ENGL.G9.WRITIN.T15_EMAILS', 'english', 9, 'Identify the elements of an email and write one', ARRAY['ENGL.G9.WRITIN.T15_EMAILS.a', 'ENGL.G9.WRITIN.T15_EMAILS.b']::text[], 'The child writes an email with the receiver''s address, a clear subject line, a greeting that suits the reader, short paragraphs, a closing and the name, and mentions any attachment. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write an email to","what is missing","write a subject line"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM', 'ENGL.G8.LISTEN.T1_POLITE_LANGUAGE_TELE.TELEPHONE_ETIQUETTE', 'skill', 'essential', 'Grade 8 English taught it first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
