INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'ENGL.G8.LISTEN.T6_CONVERSATIONAL_SKILL.DISAGREE_POLITELY', 'skill', 'essential', 'Grade 8 English taught it first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'ENGL.G8.LISTEN.T10_ORAL_PRESENTATIONS.SPEECH', 'skill', 'essential', 'Grade 8 English taught it first. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
