INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM.M9_EU_BLUNT', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM', 'Uses a blunt word where tact is needed.', '{"question":"Tell a classmate gently that her grandfather has died.","wrong_answer":"Your grandfather is dead.","correct_answer":"I am sorry; your grandfather has passed away."}'::jsonb, 'Euphemisms are not used in everyday talk.', 'Offer "Your grandfather is dead." beside "I am sorry; your grandfather has passed away." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose a gentle expression: passed away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM.M9_EU_LITERAL', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM', 'Takes a euphemism literally.', '{"question":"\"He is between jobs.\" Meaning?","wrong_answer":"He works two jobs.","correct_answer":"He has no job at the moment."}'::jsonb, 'The words are read one by one.', 'Offer "He works two jobs." beside "He has no job at the moment." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A euphemism softens a hard fact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM.M9_EU_OVERUSE', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM', 'Uses a euphemism where plain words are clearer and needed.', '{"question":"A nurse explaining a medicine dose to a patient should say ...","wrong_answer":"take a little when you feel like it","correct_answer":"take two tablets every eight hours"}'::jsonb, 'Politeness is mistaken for vagueness.', 'Offer "take a little when you feel like it" beside "take two tablets every eight hours" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Be gentle, but give facts plainly when people need them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM.M9_EU_INSULT', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.EUPHEMISM', 'Uses a "polite" word that still mocks.', '{"question":"Polite way to describe an older person?","wrong_answer":"old-timer","correct_answer":"senior citizen"}'::jsonb, 'Slang is mistaken for politeness.', 'Offer "old-timer" beside "senior citizen" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose words the person would be happy to hear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE.M9_DB_ATTACK_SPEAKER', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'Attacks the opponent instead of the argument.', '{"question":"Rebut: \"Social media helps learning.\"","wrong_answer":"My opponent is lazy and uses phones all day.","correct_answer":"My opponent claims it helps learning, but many hours go to entertainment."}'::jsonb, 'Debate is seen as a fight.', 'Offer "My opponent is lazy and uses phones all day." beside "My opponent claims it helps learning, but many hours go to entertainment." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rebut the point, not the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE.M9_DB_NO_CHAIR', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'Does not address the chair and the house.', '{"question":"How does a debater begin?","wrong_answer":"I think ...","correct_answer":"Madam Chair, members of the house, ..."}'::jsonb, 'Debate conventions are not known.', 'Offer "I think ..." beside "Madam Chair, members of the house, ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Address the chair and the house first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE.M9_DB_NO_EVIDENCE', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'Argues with feelings and no evidence.', '{"question":"Support: \"Trees should be planted in every school.\"","wrong_answer":"Because I like trees.","correct_answer":"Trees give shade and clean air; our school is hot."}'::jsonb, 'Opinions are offered without support.', 'Offer "Because I like trees." beside "Trees give shade and clean air; our school is hot." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give a reason and an example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE.M9_DB_OVERTIME', 'ENGL.G9.LISTEN.T1_POLITE_LANGUAGE.DEBATE', 'Ignores the time limit.', '{"question":"You have three minutes. You talk for seven.","wrong_answer":"That is fine.","correct_answer":"Stop when the bell rings; summarise."}'::jsonb, 'Time limits are not respected.', 'Offer "That is fine." beside "Stop when the bell rings; summarise." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan to fit the time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING.M9_IR_NO_LOG', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING', 'Keeps no reading log or portfolio.', '{"question":"How do you track your reading?","wrong_answer":"I remember","correct_answer":"a reading log"}'::jsonb, 'Records feel like extra work.', 'Offer "I remember" beside "a reading log" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Log each text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING.M9_IR_ONE_SOURCE', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING', 'Reads only print or only digital texts.', '{"question":"Your log has only websites. Add?","wrong_answer":"more websites","correct_answer":"a print novel"}'::jsonb, 'Comfort reading.', 'Offer "more websites" beside "a print novel" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Mix print and digital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING.M9_IR_LOG_TITLES', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING', 'Logs only titles with no comment.', '{"question":"What should a log entry include?","wrong_answer":"the title only","correct_answer":"title, what it was about, what I thought"}'::jsonb, 'The log is seen as a list.', 'Offer "the title only" beside "title, what it was about, what I thought" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add a line on content and opinion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING.M9_IR_TOO_EASY', 'ENGL.G9.READIN.T1_INDEPENDENT_READING_.INDEPENDENT_READING', 'Reads only texts far below grade level.', '{"question":"Your log has picture books only. Fit for Grade 9?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Easy reading feels good.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose grade-appropriate texts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.GENDER_NEUTRAL.M_EN9_GN_CHAIRMAN', 'ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.GENDER_NEUTRAL', 'Keeps chairman for any chair.', '{"question":"Which is gender-neutral?","wrong_answer":"chairman","correct_answer":"chairperson"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "chairman" next to the right answer and ask the question again in a new situation.', 'Chairperson does not assume the sex of the chair.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
