INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.GENDER_NEUTRAL.M9_GN_HE_GENERIC', 'ENGL.G9.GRAMMA.T1_GENDER_NEUTRAL_LANGU.GENDER_NEUTRAL', 'Uses he for anyone whose gender is not known.', '{"question":"Every learner should bring ___ book.","wrong_answer":"his","correct_answer":"their (or his or her)"}'::jsonb, 'He is taught as the default pronoun.', 'Offer "his" beside "their (or his or her)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use their, or his or her, when the person could be anyone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
