INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S.PL_STRUCTURE.M9_PL_ACT_SCENE', 'ENGL.G9.READIN.T1_PLAY_STRUCTURE_AND_S.PL_STRUCTURE', 'Mixes up acts and scenes.', '{"question":"A play is divided into big parts called ___, and these into ___.","wrong_answer":"scenes, acts","correct_answer":"acts, scenes"}'::jsonb, 'The two words are new together.', 'Offer "scenes, acts" beside "acts, scenes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Acts are the big parts; scenes are inside acts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN.LEGIBILITY.M9_LG_NO_INDENT', 'ENGL.G9.WRITIN.T1_LEGIBILITY_AND_NEATN.LEGIBILITY', 'Does not indent paragraphs.', '{"question":"How do you show a new paragraph?","wrong_answer":"start at the margin","correct_answer":"indent the first line"}'::jsonb, 'Indentation is skipped.', 'Offer "start at the margin" beside "indent the first line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Indent each new paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
