INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.SHORT_FORMS.M9_SF_RIDDLE_PROVERB', 'ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.SHORT_FORMS', 'Calls a proverb a riddle.', '{"question":"\"A fool and his money are soon parted\" is a ...","wrong_answer":"riddle","correct_answer":"proverb"}'::jsonb, 'Both are short oral forms.', 'Offer "riddle" beside "proverb" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A riddle asks for an answer; a proverb teaches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
