INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.SHORT_FORMS.M9_SF_OPENING', 'ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.SHORT_FORMS', 'Does not know the riddle opening and response.', '{"question":"In many Kenyan communities a riddle starts with the call \"Kitendawili\". The listeners answer ...","wrong_answer":"nothing","correct_answer":"\"Tega\""}'::jsonb, 'The convention is not taught in English.', 'Offer "nothing" beside ""Tega"" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Riddles have a call and response before the puzzle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.PERFORM_ORAL.M9_PO_MUMBLE', 'ENGL.G9.LISTEN.T2_ORAL_LITERATURE_SHOR.PERFORM_ORAL', 'Mumbles a tongue twister to get speed.', '{"question":"Perform \"Red lorry, yellow lorry\".","wrong_answer":"fast but unclear","correct_answer":"clear first, then faster"}'::jsonb, 'Speed is the goal.', 'Offer "fast but unclear" beside "clear first, then faster" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Clear sounds first, then speed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
