INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_SI.RP_STYLE.M9_RP_REPEAT_NO_FUNCTION', 'ENGL.G9.READIN.T2_INTENSIVE_READING_SI.RP_STYLE', 'Finds repetition but cannot say its function.', '{"question":"Why does the poet repeat \"Save the sea\"?","wrong_answer":"because it is repeated","correct_answer":"to stress the urgent message"}'::jsonb, 'Function of devices is not considered.', 'Offer "because it is repeated" beside "to stress the urgent message" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what the repetition adds: stress, rhythm or feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS.M_EN9_QT_MUCH', 'ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS', 'Uses much with count nouns.', '{"question":"Which is correct: ___ chairs?","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "much" next to the right answer and ask the question again in a new situation.', 'Use many with count nouns such as chairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS.M_EN9_QT_MANY', 'ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS', 'Uses many with non-count nouns.', '{"question":"Which is correct: ___ water?","wrong_answer":"many","correct_answer":"much"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "many" next to the right answer and ask the question again in a new situation.', 'Use much with non-count nouns such as water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS.M_EN9_QT_FEW', 'ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS', 'Mixes few and little.', '{"question":"Which is correct: a ___ of milk?","wrong_answer":"few","correct_answer":"little"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "few" next to the right answer and ask the question again in a new situation.', 'Use little with non-count nouns such as milk.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS.M9_QT_A_LOT_OF', 'ENGL.G9.GRAMMA.T2_NOUNS_AND_QUANTIFIER.QUANTIFIERS', 'Writes alot or a lot without of.', '{"question":"There is ___ water in the tank.","wrong_answer":"alot","correct_answer":"a lot of"}'::jsonb, 'Speech run-together is written.', 'Offer "alot" beside "a lot of" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A lot of is three words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE.M_EN9_PL_SEQUENCE_DETAIL', 'ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE.M_EN9_PL_SEQUENCE_OPPOSITE', 'ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE.M_EN9_PL_SEQUENCE_NOTSAID', 'ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE', 'Picks something the text does not say.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is something not in the text" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must be found in the text, not added from outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE.M9_PL_STAGE_ORDER', 'ENGL.G9.READIN.T2_INTENSIVE_READING_PL.PL_SEQUENCE', 'Orders events by stage directions, not by the action.', '{"question":"Which happens first in the play?","wrong_answer":"the event described in the longest stage direction","correct_answer":"the event the characters act first"}'::jsonb, 'Directions look important.', 'Offer "the event described in the longest stage direction" beside "the event the characters act first" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Follow what happens on stage in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS.M_EN9_QB_BRACKET', 'ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS', 'Uses brackets for speech.', '{"question":"What goes in double quotation marks?","wrong_answer":"Extra explanations","correct_answer":"The exact words spoken"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Extra explanations" next to the right answer and ask the question again in a new situation.', 'Quotation marks hold the exact words spoken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS.M_EN9_QB_EXTRA', 'ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS', 'Uses quotation marks for extra information.', '{"question":"What goes in brackets?","wrong_answer":"The exact words spoken","correct_answer":"Extra information"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "The exact words spoken" next to the right answer and ask the question again in a new situation.', 'Brackets hold extra information.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS.M_EN9_QB_END', 'ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS', 'Puts the full stop outside the speech.', '{"question":"Which is punctuated correctly?","wrong_answer":"She said, \"I am ready\".","correct_answer":"She said, \"I am ready.\""}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She said, "I am ready"." next to the right answer and ask the question again in a new situation.', 'The full stop goes inside the closing quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS.M9_QB_BRACKETS_SPEECH', 'ENGL.G9.WRITIN.T2_MECHANICS_OF_WRITING.QUOTES_BRACKETS', 'Puts spoken words in brackets.', '{"question":"Write: Juma said I am ready.","wrong_answer":"Juma said (I am ready).","correct_answer":"Juma said, \"I am ready.\""}'::jsonb, 'Brackets and quotation marks are both "around words".', 'Offer "Juma said (I am ready)." beside "Juma said, "I am ready."" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Quotation marks for spoken words; brackets for extra information.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
