INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_READING_FOR_INFORMAT.RS_CONTEXT.M9_RS_CONTEXT_FIGURATIVE', 'ENGL.G9.READIN.T3_READING_FOR_INFORMAT.RS_CONTEXT', 'Reads a figurative phrase literally.', '{"question":"\"The town was buried in rubbish.\" Buried means ...","wrong_answer":"put under the ground","correct_answer":"covered with a lot of"}'::jsonb, 'Words are read for their first meaning.', 'Offer "put under the ground" beside "covered with a lot of" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what picture the writer is making.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_READING_FOR_INFORMAT.RS_CONNECT.M9_RS_CONNECT_DETAIL', 'ENGL.G9.READIN.T3_READING_FOR_INFORMAT.RS_CONNECT', 'Connects on a small detail rather than the main event.', '{"question":"Connect the story of a polluted river to real life.","wrong_answer":"I also have a river near home.","correct_answer":"Our river was cleaned after the county banned dumping."}'::jsonb, 'Shared details feel like links.', 'Offer "I also have a river near home." beside "Our river was cleaned after the county banned dumping." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link the main event or issue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS.M_EN9_MD_ABILITY', 'ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS', 'Uses must for ability.', '{"question":"Which shows ability?","wrong_answer":"must","correct_answer":"can"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "must" next to the right answer and ask the question again in a new situation.', 'Can shows ability.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS.M_EN9_MD_DUTY', 'ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS', 'Uses can for duty.', '{"question":"Which shows duty?","wrong_answer":"can","correct_answer":"must"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "can" next to the right answer and ask the question again in a new situation.', 'Must shows duty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS.M_EN9_MD_BASE', 'ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS', 'Uses a modal with to plus verb.', '{"question":"Which is correct?","wrong_answer":"She can to swim.","correct_answer":"She can swim."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She can to swim." next to the right answer and ask the question again in a new situation.', 'A modal is followed by the base verb with no to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS.M9_MD_PERMISSION', 'ENGL.G9.GRAMMA.T3_MODAL_AUXILIARIES.MODALS', 'Uses can for formal permission.', '{"question":"Formally asking the principal: ___ I leave early?","wrong_answer":"Can","correct_answer":"May"}'::jsonb, 'Can is used for all requests.', 'Offer "Can" beside "May" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'May is the formal word for permission.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES.M_EN9_PF_STANZA', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES', 'Calls a stanza a line.', '{"question":"What is a stanza?","wrong_answer":"One line of a poem","correct_answer":"A group of lines"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "One line of a poem" next to the right answer and ask the question again in a new situation.', 'A stanza is a group of lines.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES.M_EN9_PF_RHYME', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES', 'Says rhyme is the same first sound.', '{"question":"What is rhyme?","wrong_answer":"Same beginning sound","correct_answer":"Repeated end sounds"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Same beginning sound" next to the right answer and ask the question again in a new situation.', 'Rhyme is repeated end sounds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES.M_EN9_PF_PERSON', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES', 'Confuses personification with simile.', '{"question":"Which is personification?","wrong_answer":"as brave as a lion","correct_answer":"the wind whispered"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "as brave as a lion" next to the right answer and ask the question again in a new situation.', 'Personification gives human actions to a thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING.M9_PW_PROSE', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING', 'Writes prose sentences in a block instead of lines and stanzas.', '{"question":"How is a poem set out?","wrong_answer":"one paragraph","correct_answer":"lines grouped in stanzas"}'::jsonb, 'Poetry is seen as feeling, not form.', 'Offer "one paragraph" beside "lines grouped in stanzas" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Break it into lines and stanzas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING.M9_PW_FORCED_RHYME', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING', 'Forces rhymes that spoil the meaning.', '{"question":"Is \"The trees are green, I ate a bean\" good?","wrong_answer":"Yes","correct_answer":"No, the rhyme spoils the meaning"}'::jsonb, 'Poems are thought to need rhyme.', 'Offer "Yes" beside "No, the rhyme spoils the meaning" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Meaning first; rhyme is optional.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING.M9_PW_NO_IMAGERY', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING', 'States facts with no images.', '{"question":"Improve: \"Trees are important.\"","wrong_answer":"Trees are important.","correct_answer":"Trees stretch green arms to catch the rain."}'::jsonb, 'Facts are easier than images.', 'Offer "Trees are important." beside "Trees stretch green arms to catch the rain." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an image or personification.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING.M9_PW_NO_MESSAGE', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_WRITING', 'Writes lines with no feeling or message.', '{"question":"What should the reader feel?","wrong_answer":"nothing","correct_answer":"that we must protect our forests"}'::jsonb, 'The purpose is not thought of.', 'Offer "nothing" beside "that we must protect our forests" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose a feeling or message first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES.M9_PF_PERSONIFICATION_ANIMAL', 'ENGL.G9.READIN.T3_POEMS_STRUCTURE.POEM_FEATURES', 'Calls an animal that talks personification even when it is a fable.', '{"question":"A poem gives the sea a voice that weeps. Device?","wrong_answer":"simile","correct_answer":"personification"}'::jsonb, 'Devices are mixed.', 'Offer "simile" beside "personification" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A thing given human actions is personification.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH.M_EN9_PA_TOPIC', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH', 'Puts the topic sentence anywhere.', '{"question":"Which sentence states the main idea?","wrong_answer":"The supporting sentence","correct_answer":"The topic sentence"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "The supporting sentence" next to the right answer and ask the question again in a new situation.', 'The topic sentence states the main idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH.M_EN9_PA_UNITY', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH', 'Mixes many ideas.', '{"question":"What is unity in a paragraph?","wrong_answer":"Many different ideas","correct_answer":"One main idea"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Many different ideas" next to the right answer and ask the question again in a new situation.', 'Unity means one main idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH.M_EN9_PA_COHERENCE', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH', 'Thinks coherence is length.', '{"question":"What is coherence?","wrong_answer":"A very long paragraph","correct_answer":"Ideas in order joined by linking words"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "A very long paragraph" next to the right answer and ask the question again in a new situation.', 'Coherence means ideas flow in order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING.M9_PW2_NO_UNITY', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING', 'Puts two main ideas in one paragraph.', '{"question":"A paragraph on consumer rights also covers football. Unity?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Unity is not checked.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One idea per paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING.M9_PW2_NO_COHERENCE', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING', 'Writes ideas in no order with no links.', '{"question":"Improve the flow.","wrong_answer":"random order","correct_answer":"ordered with connectors"}'::jsonb, 'Coherence is not checked.', 'Offer "random order" beside "ordered with connectors" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Order and link ideas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING.M9_PW2_PERSON_SWITCH', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING', 'Switches between first and second person.', '{"question":"Fix: \"I went to the shop and you see the prices are high.\"","wrong_answer":"I ... you see","correct_answer":"I went to the shop and saw the prices were high."}'::jsonb, 'Speech habits.', 'Offer "I ... you see" beside "I went to the shop and saw the prices were high." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the same person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING.M9_PW2_UNDEVELOPED', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH_WRITING', 'Writes a topic sentence and stops.', '{"question":"Is one sentence a paragraph?","wrong_answer":"Yes","correct_answer":"No: add details or examples"}'::jsonb, 'Development is not understood.', 'Offer "Yes" beside "No: add details or examples" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Support the topic sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH.M9_PA_DEVELOPMENT', 'ENGL.G9.WRITIN.T3_STRUCTURE_OF_A_PARAG.PARAGRAPH', 'Misses development as a characteristic.', '{"question":"A paragraph has a topic sentence but no examples. What is missing?","wrong_answer":"nothing","correct_answer":"development"}'::jsonb, 'Only three characteristics are remembered.', 'Offer "nothing" beside "development" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Topic sentence, unity, coherence and development.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND.M9_LR_NO_JUDGEMENT', 'ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND', 'Repeats the message without judging it.', '{"question":"Is the speaker''s message on consumer laws fair?","wrong_answer":"The speaker said consumers have rights.","correct_answer":"Fair, because it protects buyers, but it ignores traders'' costs."}'::jsonb, 'Judging is not expected.', 'Offer "The speaker said consumers have rights." beside "Fair, because it protects buyers, but it ignores traders'' costs." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say whether it is fair and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND.M9_LR_WRONG_INFO', 'ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND', 'Selects the wrong piece of information.', '{"question":"The speaker gives the fine as 5,000 shillings. Fine?","wrong_answer":"50,000 shillings","correct_answer":"5,000 shillings"}'::jsonb, 'Numbers are misheard.', 'Offer "50,000 shillings" beside "5,000 shillings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note numbers exactly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND.M9_LR_SPEAKERS_MIXED', 'ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND', 'Mixes up which speaker made which point.', '{"question":"Who said the ferry is unsafe?","wrong_answer":"the first speaker","correct_answer":"the second speaker"}'::jsonb, 'Points are noted without names.', 'Offer "the first speaker" beside "the second speaker" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note each speaker''s name with the point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND.M9_LR_FEELING_NO_WORDS', 'ENGL.G9.LISTEN.T4_SELECTIVE_LISTENING.LISTEN_RESPOND', 'Expresses feelings about a poem without fitting words.', '{"question":"How does the poem make you feel?","wrong_answer":"good","correct_answer":"hopeful, because it shows young people changing their lives"}'::jsonb, 'A small stock of feeling words.', 'Offer "good" beside "hopeful, because it shows young people changing their lives" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use an exact feeling word and a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT.M_EN9_RS_PREDICT_DETAIL', 'ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT.M_EN9_RS_PREDICT_OPPOSITE', 'ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
