INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT.M9_RS_PREDICT_WISH', 'ENGL.G9.READIN.T4_INTENSIVE_READING.RS_PREDICT', 'Predicts what he or she wants to happen.', '{"question":"The clues show the trader will be caught. Predict.","wrong_answer":"he will become rich","correct_answer":"he will be caught"}'::jsonb, 'Wishes replace evidence.', 'Offer "he will become rich" beside "he will be caught" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the clues.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_KEYEVENTS.M9_RS_KEYEVENTS_MINOR', 'ENGL.G9.READIN.T4_INTENSIVE_READING.RS_KEYEVENTS', 'Lists minor events as key events.', '{"question":"Key event in a consumer story?","wrong_answer":"she bought a soda","correct_answer":"she reported the fake goods to the authorities"}'::jsonb, 'All events seem equal.', 'Offer "she bought a soda" beside "she reported the fake goods to the authorities" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Key events change the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_QUESTIONS.M9_RS_QUESTIONS_COPY', 'ENGL.G9.READIN.T4_INTENSIVE_READING.RS_QUESTIONS', 'Copies a long sentence when a short answer is asked.', '{"question":"In two words, what did the inspector find?","wrong_answer":"The inspector found that the scales had been changed so that buyers paid more.","correct_answer":"faulty scales"}'::jsonb, 'Copying feels safe.', 'Offer "The inspector found that the scales had been changed so that buyers paid more." beside "faulty scales" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Follow the word limit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_INTENSIVE_READING.RS_RELATE.M9_RS_RELATE_RETELL', 'ENGL.G9.READIN.T4_INTENSIVE_READING.RS_RELATE', 'Retells the text instead of relating it.', '{"question":"Relate the characters to real life.","wrong_answer":"The trader cheated buyers.","correct_answer":"Like the trader, some sellers in our market change scales."}'::jsonb, 'Retelling is easier.', 'Offer "The trader cheated buyers." beside "Like the trader, some sellers in our market change scales." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Name a real person or situation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT.M_EN9_PE_PRESENT', 'ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT', 'Uses had for the present perfect.', '{"question":"Which is present perfect?","wrong_answer":"She had finished.","correct_answer":"She has finished."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She had finished." next to the right answer and ask the question again in a new situation.', 'Present perfect uses have or has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT.M_EN9_PE_PAST', 'ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT', 'Uses has for the past perfect.', '{"question":"Which is past perfect?","wrong_answer":"She has finished before I came.","correct_answer":"She had finished before I came."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She has finished before I came." next to the right answer and ask the question again in a new situation.', 'Past perfect uses had.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT.M_EN9_PE_PARTICIPLE', 'ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT', 'Uses the simple past after has.', '{"question":"Which is correct?","wrong_answer":"She has went home.","correct_answer":"She has gone home."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She has went home." next to the right answer and ask the question again in a new situation.', 'Use the past participle after has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT.M9_PE_WITH_TIME', 'ENGL.G9.GRAMMA.T4_PRESENT_AND_PAST_PER.PERFECT', 'Uses the present perfect with a finished time.', '{"question":"I ___ the film yesterday. (see)","wrong_answer":"have seen","correct_answer":"saw"}'::jsonb, 'Have seen sounds more correct.', 'Offer "have seen" beside "saw" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'With yesterday, use the simple past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
