INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_.PL_CHARACTERS.M9_PL_CHARACTERS_ADVERB', 'ENGL.G9.READIN.T4_PLAY_IDENTIFICATION_.PL_CHARACTERS', 'Uses an adjective where an adverb describes an action.', '{"question":"The chief spoke ___. (angry)","wrong_answer":"angry","correct_answer":"angrily"}'::jsonb, 'The -ly rule is not applied.', 'Offer "angry" beside "angrily" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Actions are described with adverbs: angrily.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M9_PS_Y_J', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /j/ (yes) as /dʒ/ (jess).', '{"question":"Say: yes, yellow","wrong_answer":"jes, jellow","correct_answer":"yes, yellow"}'::jsonb, 'The semi-vowel is replaced by a stronger sound.', 'Offer "jes, jellow" beside "yes, yellow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Y is a glide: tongue near the roof, no stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M9_PS_W_V', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /w/ as /v/ or drops it.', '{"question":"Say: wet, west","wrong_answer":"vet, vest","correct_answer":"wet, west"}'::jsonb, 'The lip rounding is replaced.', 'Offer "vet, vest" beside "wet, west" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Round the lips for w; no teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M9_PS_DAY_DIE', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /eɪ/ (day) and /aɪ/ (die) the same.', '{"question":"Say: day, die","wrong_answer":"both the same","correct_answer":"day (ay), die (eye)"}'::jsonb, 'Diphthongs are flattened.', 'Offer "both the same" beside "day (ay), die (eye)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Day slides from e to i; die slides from a to i.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS.M9_PS_NOW_NO', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.PRONOUNCE_SOUNDS', 'Says /aʊ/ (now) like /əʊ/ (no).', '{"question":"Say: now","wrong_answer":"no","correct_answer":"now (ow)"}'::jsonb, 'Spelling o is read the same.', 'Offer "no" beside "now (ow)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Now opens wide then rounds: ah-oo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS.M9_SS_ALL_STRONG', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS', 'Stresses every word.', '{"question":"Say: She WON the MEDAL.","wrong_answer":"SHE WON THE MEDAL","correct_answer":"She WON the MEDal"}'::jsonb, 'Syllable-timed home languages.', 'Offer "SHE WON THE MEDAL" beside "She WON the MEDal" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Content words strong, function words weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS.M9_SS_WRONG_EMPHASIS', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS', 'Puts emphatic stress on a word that does not carry the contrast.', '{"question":"Not her brother: say \"She won the medal.\"","wrong_answer":"She won the MEDAL","correct_answer":"SHE won the medal"}'::jsonb, 'Stress placement by habit.', 'Offer "She won the MEDAL" beside "SHE won the medal" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stress the word that corrects or contrasts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS.M9_SS_FUNCTION_STRONG', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS', 'Stresses function words.', '{"question":"Say: The team is in the final.","wrong_answer":"THE team IS IN THE final","correct_answer":"The TEAM is in the FInal"}'::jsonb, 'Every word is given weight.', 'Offer "THE team IS IN THE final" beside "The TEAM is in the FInal" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the, is and in weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS.M9_SS_MEANING_SAME', 'ENGL.G9.LISTEN.T5_PRONUNCIATION.SENTENCE_STRESS', 'Thinks moving the stress does not change meaning.', '{"question":"Do \"I didn''t SAY she stole it\" and \"I didn''t say SHE stole it\" mean the same?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Stress is heard as accent only.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stress shows what you mean.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH.M9_RR_DICTIONARY_ONLY_MEANING', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH', 'Uses the dictionary only for meaning, not usage.', '{"question":"Is \"advice\" a noun or a verb?","wrong_answer":"I do not know","correct_answer":"check the dictionary: noun (advise is the verb)"}'::jsonb, 'Dictionaries are seen as meaning books only.', 'Offer "I do not know" beside "check the dictionary: noun (advise is the verb)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A dictionary shows part of speech and usage too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH.M9_RR_THESAURUS_SWAP', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH', 'Swaps a word for a thesaurus synonym that does not fit.', '{"question":"Replace \"big\" in \"a big mistake\".","wrong_answer":"a bulky mistake","correct_answer":"a serious mistake"}'::jsonb, 'All synonyms are thought equal.', 'Offer "a bulky mistake" beside "a serious mistake" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the synonym fits the context.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH.M9_RR_COPY', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH', 'Copies the encyclopaedia word for word.', '{"question":"How should research notes look?","wrong_answer":"copied paragraphs","correct_answer":"key points in my own words with the source"}'::jsonb, 'Copying feels safe.', 'Offer "copied paragraphs" beside "key points in my own words with the source" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note key points and the source.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH.M9_RR_WRONG_SOURCE', 'ENGL.G9.READIN.T5_REFERENCE_MATERIALS_.REFERENCE_RESEARCH', 'Uses the wrong reference for the task.', '{"question":"Facts on community policing?","wrong_answer":"a thesaurus","correct_answer":"an encyclopaedia or reliable website"}'::jsonb, 'Purposes are mixed.', 'Offer "a thesaurus" beside "an encyclopaedia or reliable website" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the reference to the need.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER.M_EN9_AO_COLOUR', 'ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER', 'Puts colour before size.', '{"question":"Which order is correct?","wrong_answer":"a red big ball","correct_answer":"a big red ball"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "a red big ball" next to the right answer and ask the question again in a new situation.', 'Size comes before colour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER.M_EN9_AO_OPINION', 'ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER', 'Puts opinion last.', '{"question":"Which order is correct?","wrong_answer":"a wooden lovely box","correct_answer":"a lovely wooden box"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "a wooden lovely box" next to the right answer and ask the question again in a new situation.', 'Opinion comes before material.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER.M_EN9_AO_AGE', 'ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER', 'Puts age after colour.', '{"question":"Which order is correct?","wrong_answer":"a brown old dog","correct_answer":"an old brown dog"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "a brown old dog" next to the right answer and ask the question again in a new situation.', 'Age comes before colour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER.M9_AO_MATERIAL', 'ENGL.G9.GRAMMA.T5_ORDER_OF_ADJECTIVES.ADJ_ORDER', 'Puts material before colour or size.', '{"question":"a ___ ___ ___ table (wooden, small, brown)","wrong_answer":"wooden small brown","correct_answer":"small brown wooden"}'::jsonb, 'The full order is not fixed.', 'Offer "wooden small brown" beside "small brown wooden" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Opinion, size, age, shape, colour, origin, material, purpose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE.M9_PS2_NO_EXAMPLE', 'ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE', 'Names a device with no example.', '{"question":"Give a feature of style.","wrong_answer":"humour","correct_answer":"humour: the servant mistakes the chief for a visitor"}'::jsonb, 'Examples are not expected.', 'Offer "humour" beside "humour: the servant mistakes the chief for a visitor" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Quote or describe an example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE.M9_PS2_NO_LINK', 'ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE', 'Names the device but not how it supports the message.', '{"question":"How does the monologue help the message?","wrong_answer":"it is a monologue","correct_answer":"it shows the hero''s fear before he decides"}'::jsonb, 'Function is not considered.', 'Offer "it is a monologue" beside "it shows the hero''s fear before he decides" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say what it shows or adds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE.M9_PS2_MONOLOGUE_DIALOGUE', 'ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE', 'Calls a dialogue a monologue.', '{"question":"One character speaks alone at length. This is ...","wrong_answer":"a dialogue","correct_answer":"a monologue"}'::jsonb, 'The two words are close.', 'Offer "a dialogue" beside "a monologue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Mono means one speaker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE.M9_PS2_IRONY', 'ENGL.G9.READIN.T5_PLAY_STYLE_CLASS_REA.PLAY_STYLE', 'Misses irony.', '{"question":"The thief lectures others on honesty. This is ...","wrong_answer":"dialogue","correct_answer":"irony"}'::jsonb, 'Irony is subtle.', 'Offer "dialogue" beside "irony" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Irony is when the opposite of what is expected happens or is said.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION.M_EN9_LA_CLOSE', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION', 'Uses Yours sincerely with Sir or Madam.', '{"question":"Which closing goes with Dear Sir or Madam?","wrong_answer":"Yours sincerely","correct_answer":"Yours faithfully"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Yours sincerely" next to the right answer and ask the question again in a new situation.', 'Yours faithfully goes with Dear Sir or Madam.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION.M_EN9_LA_SUBJECT', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION', 'Leaves out the subject line.', '{"question":"Which part states what the letter is about?","wrong_answer":"The signature","correct_answer":"The subject line"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "The signature" next to the right answer and ask the question again in a new situation.', 'The subject line states what the letter is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION.M_EN9_LA_ADDRESS', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION', 'Puts the sender''s address at the bottom.', '{"question":"Where does the writer''s address go?","wrong_answer":"At the bottom","correct_answer":"At the top"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "At the bottom" next to the right answer and ask the question again in a new situation.', 'The writer''s address goes at the top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER.M9_AL_FRIENDLY_TONE', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER', 'Writes in a friendly tone.', '{"question":"Opening for an application?","wrong_answer":"Hi! How are you?","correct_answer":"I wish to apply for a place in Grade 10 at your school."}'::jsonb, 'Friendly letter habits.', 'Offer "Hi! How are you?" beside "I wish to apply for a place in Grade 10 at your school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Formal and direct.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER.M9_AL_NO_QUALIFICATIONS', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER', 'Does not say why he or she is suitable.', '{"question":"What else must the body say?","wrong_answer":"nothing","correct_answer":"my results, interests and activities"}'::jsonb, 'The request is thought enough.', 'Offer "nothing" beside "my results, interests and activities" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give reasons you are suitable.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER.M9_AL_SINCERELY', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER', 'Closes with Yours sincerely after Dear Sir.', '{"question":"Dear Sir ... closing?","wrong_answer":"Yours sincerely","correct_answer":"Yours faithfully"}'::jsonb, 'The pairing rule is not known.', 'Offer "Yours sincerely" beside "Yours faithfully" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Dear Sir: Yours faithfully.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER.M9_AL_BEGGING', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.APPLICATION_LETTER', 'Begs instead of applying confidently.', '{"question":"Which suits an application?","wrong_answer":"Please, please take me, I am suffering.","correct_answer":"I would be grateful to be considered."}'::jsonb, 'Need is mixed with request.', 'Offer "Please, please take me, I am suffering." beside "I would be grateful to be considered." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Be polite and confident.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION.M9_LA_FRIENDLY_OPENING', 'ENGL.G9.WRITIN.T5_LETTER_OF_APPLICATIO.LETTER_APPLICATION', 'Opens with a friendly greeting.', '{"question":"Opening of an application?","wrong_answer":"Hi! I hope you are well.","correct_answer":"I wish to apply for a place in your school."}'::jsonb, 'Friendly letter habits.', 'Offer "Hi! I hope you are well." beside "I wish to apply for a place in your school." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Go straight to the purpose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION.M9_NG_DEMAND', 'ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION', 'Makes demands instead of offers.', '{"question":"You want a lower price for the football. Say ...","wrong_answer":"Give it to me for 500.","correct_answer":"Would you consider 500 if I buy two?"}'::jsonb, 'Negotiation is seen as winning.', 'Offer "Give it to me for 500." beside "Would you consider 500 if I buy two?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Offer something in return.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION.M9_NG_NO_LISTEN', 'ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION', 'Does not listen to the other side''s needs.', '{"question":"The seller says she must cover her costs. You ...","wrong_answer":"repeat your price","correct_answer":"ask what price covers her costs"}'::jsonb, 'Only one side is considered.', 'Offer "repeat your price" beside "ask what price covers her costs" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen and find a middle point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION.M9_NG_WALK_AWAY', 'ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION', 'Gives up at the first "no".', '{"question":"The seller says no to 500. Next?","wrong_answer":"walk away angry","correct_answer":"How about we meet halfway at 600?"}'::jsonb, 'Negotiation is not seen as a process.', 'Offer "walk away angry" beside "How about we meet halfway at 600?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a counter-offer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION.M9_NG_HOSTILE_CUES', 'ENGL.G9.LISTEN.T6_CONVERSATIONAL_SKILL.NEGOTIATION', 'Uses hostile body language.', '{"question":"Which cue helps a negotiation?","wrong_answer":"folded arms and a frown","correct_answer":"open hands and eye contact"}'::jsonb, 'Cues are not noticed.', 'Offer "folded arms and a frown" beside "open hands and eye contact" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep calm, open cues.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M9_RF_STOPS_UNKNOWN', 'ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Stops at every unknown word.', '{"question":"You meet an unknown word while reading aloud.","wrong_answer":"stop and wait","correct_answer":"say it as best you can and read on"}'::jsonb, 'Fear of mistakes.', 'Offer "stop and wait" beside "say it as best you can and read on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the flow; check later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M9_RF_RUSH', 'ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Rushes and loses accuracy.', '{"question":"Read the passage on leisure.","wrong_answer":"very fast with slips","correct_answer":"steady and accurate"}'::jsonb, 'Fast is mistaken for fluent.', 'Offer "very fast with slips" beside "steady and accurate" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Steady pace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M9_RF_FLAT', 'ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Reads with no expression.', '{"question":"Read: \"We won!\" shouted the fans.","wrong_answer":"flat","correct_answer":"excited"}'::jsonb, 'Expression not linked to meaning.', 'Offer "flat" beside "excited" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Show the feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY.M9_RF_NO_WAYS', 'ENGL.G9.READIN.T6_READING_FLUENCY.READ_FLUENTLY', 'Cannot name ways of improving fluency.', '{"question":"One way to improve fluency?","wrong_answer":"read loud","correct_answer":"read in phrases"}'::jsonb, 'Fluency is seen as talent.', 'Offer "read loud" beside "read in phrases" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Preview, phrase, pause, vary, pace.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES.M_EN9_AD_MORE', 'ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES', 'Uses -er with long adverbs.', '{"question":"Which is correct?","wrong_answer":"carefullier","correct_answer":"more carefully"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "carefullier" next to the right answer and ask the question again in a new situation.', 'Long adverbs take more and most.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES.M_EN9_AD_SUPER', 'ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES', 'Uses the comparative for the superlative.', '{"question":"Who ran ___ of all?","wrong_answer":"faster","correct_answer":"fastest"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "faster" next to the right answer and ask the question again in a new situation.', 'Use the superlative when comparing three or more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES.M_EN9_AD_THAN', 'ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES', 'Uses the positive with than.', '{"question":"Which is correct?","wrong_answer":"She sings well than I do.","correct_answer":"She sings better than I do."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She sings well than I do." next to the right answer and ask the question again in a new situation.', 'Use the comparative with than.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES.M9_AD_IRREGULAR', 'ENGL.G9.GRAMMA.T6_COMPARISON_OF_ADVERB.ADVERB_DEGREES', 'Adds -er to an irregular adverb.', '{"question":"She sings ___ than me. (well)","wrong_answer":"weller","correct_answer":"better"}'::jsonb, 'The -er rule is overused.', 'Offer "weller" beside "better" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Well, better, best; badly, worse, worst.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES.M_EN9_PL_THEMES_DETAIL', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES.M_EN9_PL_THEMES_OPPOSITE', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES.M_EN9_PL_THEMES_NOTSAID', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES', 'Picks something the text does not say.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is something not in the text" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must be found in the text, not added from outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES.M9_PL_THEME_TOPIC', 'ENGL.G9.READIN.T6_INTENSIVE_READING_PL.PL_THEMES', 'Gives a topic word as a theme.', '{"question":"Theme of a play about a corrupt chief?","wrong_answer":"chief","correct_answer":"corruption destroys trust"}'::jsonb, 'Topic and theme are not told apart.', 'Offer "chief" beside "corruption destroys trust" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A theme is an idea about life, said as a phrase.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M_EN9_SG_HOMOPHONE', 'ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Mixes their and there.', '{"question":"Which is correct: ___ books are on the table.","wrong_answer":"There","correct_answer":"Their"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "There" next to the right answer and ask the question again in a new situation.', 'Their shows belonging.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M_EN9_SG_SEPARATE', 'ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Misspells separate.', '{"question":"Which is spelt correctly?","wrong_answer":"seperate","correct_answer":"separate"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "seperate" next to the right answer and ask the question again in a new situation.', 'Separate has "par" in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M_EN9_SG_COMMITTEE', 'ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Misspells committee.', '{"question":"Which is spelt correctly?","wrong_answer":"comitee","correct_answer":"committee"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "comitee" next to the right answer and ask the question again in a new situation.', 'Committee has double m, double t and double e.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING.M9_SG_HOMONYM', 'ENGL.G9.WRITIN.T6_MECHANICS_OF_WRITING.SPELLING', 'Uses the wrong meaning of a homonym.', '{"question":"\"She will bear the pain.\" Bear means ...","wrong_answer":"a wild animal","correct_answer":"to put up with"}'::jsonb, 'The first meaning learnt is used.', 'Offer "a wild animal" beside "to put up with" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the sentence to pick the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE.M9_IE_SAME', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE', 'Treats interpreting and evaluating as the same.', '{"question":"\"Is the writer''s claim reliable?\" asks you to ...","wrong_answer":"interpret","correct_answer":"evaluate"}'::jsonb, 'Both mean thinking about a text.', 'Offer "interpret" beside "evaluate" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Interpret: what it means. Evaluate: how good or true it is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE.M9_IE_ACCEPT_ALL', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE', 'Accepts every claim as true.', '{"question":"An advert says a drink makes you a champion. Reliable?","wrong_answer":"Yes","correct_answer":"No, it is an advertising claim"}'::jsonb, 'Printed claims seem true.', 'Offer "Yes" beside "No, it is an advertising claim" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask who says it and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE.M9_IE_LITERAL', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE', 'Interprets figurative language literally.', '{"question":"\"The sea of plastic\" means ...","wrong_answer":"a sea made of plastic","correct_answer":"a very large amount of plastic waste"}'::jsonb, 'Figurative language read literally.', 'Offer "a sea made of plastic" beside "a very large amount of plastic waste" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the picture the writer means.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE.M9_IE_OPINION_NO_REASON', 'ENGL.G9.READIN.T7_INTENSIVE_READING_IN.INTERPRET_EVALUATE', 'Evaluates with no reason.', '{"question":"Is the article fair?","wrong_answer":"No.","correct_answer":"No, it gives only the fishermen''s side."}'::jsonb, 'Reasons are not expected.', 'Offer "No." beside "No, it gives only the fishermen''s side." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give a reason from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS.M_EN9_RP_WHICH', 'ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS', 'Uses who for things.', '{"question":"The book ___ I read was long.","wrong_answer":"who","correct_answer":"which"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "who" next to the right answer and ask the question again in a new situation.', 'Use which for things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS.M_EN9_RP_WHOSE', 'ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS', 'Uses who for belonging.', '{"question":"The girl ___ bag was lost cried.","wrong_answer":"who","correct_answer":"whose"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "who" next to the right answer and ask the question again in a new situation.', 'Whose shows belonging.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS.M_EN9_RP_WHO', 'ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS', 'Uses which for people.', '{"question":"The man ___ helped us is kind.","wrong_answer":"which","correct_answer":"who"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "which" next to the right answer and ask the question again in a new situation.', 'Use who for people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS.M9_RP_WHOM', 'ENGL.G9.GRAMMA.T7_RELATIVE_PRONOUNS_IN.RELATIVE_PRONOUNS', 'Uses who after a preposition.', '{"question":"The man to ___ I spoke was the chief.","wrong_answer":"who","correct_answer":"whom"}'::jsonb, 'Whom is rare in speech.', 'Offer "who" beside "whom" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After to, for, with: whom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
