INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T7_INTENSIVE_READING_PL.PL_RELATIONSHIP.M9_PL_REL_ONE_WAY', 'ENGL.G9.READIN.T7_INTENSIVE_READING_PL.PL_RELATIONSHIP', 'Describes a relationship from one side only.', '{"question":"How do the father and son relate?","wrong_answer":"the father loves the son","correct_answer":"the father is strict and the son resents him, until they reconcile"}'::jsonb, 'One side is noticed.', 'Offer "the father loves the son" beside "the father is strict and the son resents him, until they reconcile" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe how each treats the other, and how it changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS.M9_WP_ORDER', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS', 'Puts stages in the wrong order.', '{"question":"Order: publishing, drafting, prewriting.","wrong_answer":"publishing first","correct_answer":"prewriting, drafting, publishing"}'::jsonb, 'Stages learnt as a list.', 'Offer "publishing first" beside "prewriting, drafting, publishing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan, draft, revise, edit, publish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS.M9_WP_REVISE_EDIT', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS', 'Mixes revising and editing.', '{"question":"Fixing spelling is ...","wrong_answer":"revising","correct_answer":"editing"}'::jsonb, 'Both mean changing.', 'Offer "revising" beside "editing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Revise ideas; edit mechanics.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS.M9_WP_ONE_DRAFT', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS', 'Thinks the first draft is final.', '{"question":"After the first draft you ...","wrong_answer":"hand it in","correct_answer":"revise and edit"}'::jsonb, 'Drafting is seen as the end.', 'Offer "hand it in" beside "revise and edit" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Always revise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS.M9_WP_SKIP_PLAN', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.WRITING_PROCESS', 'Skips prewriting.', '{"question":"Is planning needed for a short story?","wrong_answer":"No","correct_answer":"Yes"}'::jsonb, 'Short texts seem not to need it.', 'Offer "No" beside "Yes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan every text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION.M9_NC_NO_CLIMAX', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION', 'Writes a story with no climax.', '{"question":"What makes the middle exciting?","wrong_answer":"more events","correct_answer":"a turning point the events build to"}'::jsonb, 'Stories are lists of events.', 'Offer "more events" beside "a turning point the events build to" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Build to a climax.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION.M9_NC_UNBELIEVABLE', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION', 'Writes events with no background, so they are not believable.', '{"question":"Why is the sudden rescue hard to believe?","wrong_answer":"it is fine","correct_answer":"nothing prepared us for the rescuer"}'::jsonb, 'Background is not planned.', 'Offer "it is fine" beside "nothing prepared us for the rescuer" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Prepare the reader with background details.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION.M9_NC_IDIOM_MISUSE', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION', 'Uses an idiom with the wrong meaning.', '{"question":"\"The voyage was plain sailing\" for a stormy trip?","wrong_answer":"Yes","correct_answer":"No: plain sailing means easy"}'::jsonb, 'Idioms read literally.', 'Offer "Yes" beside "No: plain sailing means easy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use idioms for their real meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION.M9_NC_TENSE', 'ENGL.G9.WRITIN.T7_THE_WRITING_PROCESS.NARRATIVE_COMPOSITION', 'Switches tense.', '{"question":"Correct: The ship left and sails away.","wrong_answer":"left ... sails","correct_answer":"left ... sailed"}'::jsonb, 'Present slips in.', 'Offer "left ... sails" beside "left ... sailed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Past tense throughout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV.M_EN9_RP_POV_DETAIL', 'ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV.M_EN9_RP_POV_OPPOSITE', 'ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV.M_EN9_RP_POV_NOTSAID', 'ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV', 'Picks something the text does not say.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is something not in the text" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must be found in the text, not added from outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV.M9_RP_POV_PERSON', 'ENGL.G9.READIN.T8_READING_FOR_INTERPRE.RP_POV', 'Confuses point of view with the person in the poem.', '{"question":"A poem says \"you must save the forest.\" Point of view?","wrong_answer":"the forest","correct_answer":"second person, addressing the reader"}'::jsonb, 'Point of view is new.', 'Offer "the forest" beside "second person, addressing the reader" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point of view is who speaks and to whom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS.M_EN9_CP_BECAUSE', 'ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS', 'Uses because without of before a noun.', '{"question":"We stayed in ___ the rain.","wrong_answer":"because","correct_answer":"because of"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "because" next to the right answer and ask the question again in a new situation.', 'Because of is followed by a noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS.M_EN9_CP_INSTEAD', 'ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS', 'Uses instead without of.', '{"question":"She took tea ___ coffee.","wrong_answer":"instead","correct_answer":"instead of"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "instead" next to the right answer and ask the question again in a new situation.', 'Instead of is followed by a noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS.M_EN9_CP_ACCORDING', 'ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS', 'Uses according with from.', '{"question":"It happened ___ the report.","wrong_answer":"according from","correct_answer":"according to"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "according from" next to the right answer and ask the question again in a new situation.', 'Use according to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS.M9_CP_IN_SPITE', 'ENGL.G9.GRAMMA.T8_COMPLEX_PREPOSITIONS.COMPLEX_PREPS', 'Writes in spite without of.', '{"question":"___ the rain, the match went on.","wrong_answer":"In spite","correct_answer":"In spite of"}'::jsonb, 'The full form is not known.', 'Offer "In spite" beside "In spite of" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In spite of, because of, instead of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
