INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T8_POETRY_CHARACTERS.RP_PERSONA.M9_RP_PERSONA_LISTENER', 'ENGL.G9.READIN.T8_POETRY_CHARACTERS.RP_PERSONA', 'Names the listener as the persona.', '{"question":"\"Child, listen to me,\" says the mother in the poem. Persona?","wrong_answer":"the child","correct_answer":"the mother"}'::jsonb, 'Persona and addressee are mixed.', 'Offer "the child" beside "the mother" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The persona is the speaker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T8_ASSESSING_WRITING.ASSESS_WRITING.M9_AW_LENGTH', 'ENGL.G9.WRITIN.T8_ASSESSING_WRITING.ASSESS_WRITING', 'Judges by length.', '{"question":"Which composition is better?","wrong_answer":"the longest","correct_answer":"the one that meets the criteria"}'::jsonb, 'Length is visible.', 'Offer "the longest" beside "the one that meets the criteria" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the criteria.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
