INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.CORRELATIVE.M_EN9_CO_NOTONLY', 'ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.CORRELATIVE', 'Pairs not only with and.', '{"question":"Not only tall ___ also strong.","wrong_answer":"and","correct_answer":"but"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "and" next to the right answer and ask the question again in a new situation.', 'Not only goes with but also.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.CORRELATIVE.M9_CO_WHETHER', 'ENGL.G9.GRAMMA.T9_CONJUNCTIONS_CORRELA.CORRELATIVE', 'Uses whether ... nor.', '{"question":"I do not know ___ to stay or go.","wrong_answer":"whether ... nor","correct_answer":"whether ... or"}'::jsonb, 'Pairs are mixed.', 'Offer "whether ... nor" beside "whether ... or" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Whether goes with or.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
