INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.NARRATIVE_ELEMENTS.M_EN9_NE_CLIMAX', 'ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.NARRATIVE_ELEMENTS', 'Says climax is the ending.', '{"question":"What is the climax?","wrong_answer":"The last line","correct_answer":"The most exciting point"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "The last line" next to the right answer and ask the question again in a new situation.', 'The climax is the most exciting point.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.NARRATIVE_ELEMENTS.M9_NE_RESOLUTION', 'ENGL.G9.WRITIN.T9_NARRATIVE_COMPOSITIO.NARRATIVE_ELEMENTS', 'Thinks the resolution is the climax.', '{"question":"The part where the problem is solved is the ...","wrong_answer":"climax","correct_answer":"resolution"}'::jsonb, 'Both come near the end.', 'Offer "climax" beside "resolution" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Climax: the most exciting point. Resolution: how it ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH.M9_IS_NO_PLAN', 'ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH', 'Starts speaking with no plan and wanders.', '{"question":"You get the topic \"Social media\". First?","wrong_answer":"start talking at once","correct_answer":"take a moment to choose a position and two points"}'::jsonb, 'Impromptu is taken to mean unplanned.', 'Offer "start talking at once" beside "take a moment to choose a position and two points" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan quickly: position, two points, close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH.M9_IS_FREEZE', 'ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH', 'Freezes and says nothing.', '{"question":"You cannot think of anything. What helps?","wrong_answer":"stay silent","correct_answer":"use a simple frame: I think ... because ... for example ..."}'::jsonb, 'Fear of saying the wrong thing.', 'Offer "stay silent" beside "use a simple frame: I think ... because ... for example ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use a frame to start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH.M9_IS_NO_CLOSE', 'ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH', 'Stops suddenly with no close.', '{"question":"How should you end?","wrong_answer":"That is all.","correct_answer":"So, social media is useful if used wisely. Thank you."}'::jsonb, 'Endings are not planned.', 'Offer "That is all." beside "So, social media is useful if used wisely. Thank you." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sum up and thank the audience.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH.M9_IS_OFF_TOPIC', 'ENGL.G9.LISTEN.T10_IMPROMPTU_SPEECHES.IMPROMPTU_SPEECH', 'Drifts to a topic he or she knows better.', '{"question":"Topic: mass media. The speaker talks about football.","wrong_answer":"That is fine.","correct_answer":"Keep to mass media."}'::jsonb, 'Comfort topics take over.', 'Offer "That is fine." beside "Keep to mass media." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Link every point to the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING.M9_NM_ONE_SIDE', 'ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING', 'Notes only one side of an argument.', '{"question":"The passage argues both sides of social media. Notes?","wrong_answer":"only the benefits","correct_answer":"benefits and harms under two headings"}'::jsonb, 'Agreeing side noticed more.', 'Offer "only the benefits" beside "benefits and harms under two headings" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING.M9_NM_COPIES', 'ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING', 'Copies sentences.', '{"question":"How do you note?","wrong_answer":"copy","correct_answer":"key words"}'::jsonb, 'Copying feels safe.', 'Offer "copy" beside "key words" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Key words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING.M9_NM_EVIDENCE_AS_POINT', 'ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING', 'Notes the evidence instead of the point.', '{"question":"Main point?","wrong_answer":"60% of youth use TikTok","correct_answer":"social media takes much of young people''s time"}'::jsonb, 'Numbers stick.', 'Offer "60% of youth use TikTok" beside "social media takes much of young people''s time" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note the point the evidence supports.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING.M9_NM_NO_POSITION', 'ENGL.G9.READIN.T10_NOTE_MAKING.NOTE_MAKING', 'Misses the writer''s position.', '{"question":"What does the writer believe overall?","wrong_answer":"not noted","correct_answer":"social media should be regulated"}'::jsonb, 'The conclusion is skipped.', 'Offer "not noted" beside "social media should be regulated" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Note the writer''s position first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM.M_EN9_DN_ORDINAL', 'ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM', 'Uses a cardinal for position.', '{"question":"Which shows position?","wrong_answer":"five","correct_answer":"fifth"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "five" next to the right answer and ask the question again in a new situation.', 'Ordinals show position.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM.M_EN9_DN_CARDINAL', 'ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM', 'Uses an ordinal for counting.', '{"question":"Which shows how many?","wrong_answer":"fifth","correct_answer":"five"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "fifth" next to the right answer and ask the question again in a new situation.', 'Cardinals show how many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM.M_EN9_DN_ORDER', 'ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM', 'Puts the determiner after the noun.', '{"question":"Which is correct?","wrong_answer":"books three","correct_answer":"three books"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "books three" next to the right answer and ask the question again in a new situation.', 'A determiner comes before the noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM.M9_DN_FIRST_TWO', 'ENGL.G9.GRAMMA.T10_DETERMINERS_NUMERALS.DETERMINERS_NUM', 'Puts the cardinal before the ordinal.', '{"question":"The ___ ___ learners (first, two)","wrong_answer":"two first","correct_answer":"first two"}'::jsonb, 'Order of numerals is not known.', 'Offer "two first" beside "first two" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ordinal before cardinal: the first two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES.M9_PC_EXPENSIVE', 'ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES', 'Thinks props must be expensive.', '{"question":"A crown for the chief?","wrong_answer":"buy a gold crown","correct_answer":"make one from card"}'::jsonb, 'Props are pictured as costly.', 'Offer "buy a gold crown" beside "make one from card" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Simple props work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES.M9_PC_MOOD_MISMATCH', 'ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES', 'Chooses a prop that fights the mood.', '{"question":"A sad funeral scene: which prop?","wrong_answer":"balloons","correct_answer":"a dim lantern"}'::jsonb, 'Mood is not considered.', 'Offer "balloons" beside "a dim lantern" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match props to the mood.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES.M9_PC_TOO_MANY', 'ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES', 'Fills the stage with props.', '{"question":"How many props does a scene need?","wrong_answer":"as many as possible","correct_answer":"a few that matter"}'::jsonb, 'More seems better.', 'Offer "as many as possible" beside "a few that matter" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A few props that matter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES.M9_PC_COSTUME_ERA', 'ENGL.G9.READIN.T10_PLAY_PROJECT.PROPS_COSTUMES', 'Chooses a costume from the wrong time or place.', '{"question":"A play set in a 1950s village: costume?","wrong_answer":"jeans and a phone","correct_answer":"a simple kanga or shuka"}'::jsonb, 'Setting is ignored.', 'Offer "jeans and a phone" beside "a simple kanga or shuka" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match costume to setting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS.M9_BF_WRONG_FORM', 'ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS', 'Picks the wrong form.', '{"question":"Which is a bursary form?","wrong_answer":"a library card form","correct_answer":"a CDF bursary application form"}'::jsonb, 'Form types are not known.', 'Offer "a library card form" beside "a CDF bursary application form" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the heading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS.M9_BF_INCOMPLETE', 'ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS', 'Leaves sections blank.', '{"question":"The form asks for parents'' income. You ...","wrong_answer":"leave it blank","correct_answer":"fill it accurately"}'::jsonb, 'Hard questions are skipped.', 'Offer "leave it blank" beside "fill it accurately" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer every section.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS.M9_BF_NO_DOCUMENTS', 'ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS', 'Forgets the documents to attach.', '{"question":"What else does the form need?","wrong_answer":"nothing","correct_answer":"the attachments listed (birth certificate, results slip)"}'::jsonb, 'Attachments are overlooked.', 'Offer "nothing" beside "the attachments listed (birth certificate, results slip)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the list of attachments.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS.M9_BF_UNSIGNED', 'ENGL.G9.WRITIN.T10_FILLING_FORMS_APPLIC.BURSARY_FORMS', 'Leaves the declaration unsigned.', '{"question":"Is the form complete without the signatures?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Signatures seem a formality.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sign the declaration; get the guardian''s too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW.M9_JI_NO_PREPARATION', 'ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW', 'Goes to the interview unprepared.', '{"question":"Before an interview you should ...","wrong_answer":"just go","correct_answer":"learn about the job and prepare answers"}'::jsonb, 'Preparation is not seen as part of it.', 'Offer "just go" beside "learn about the job and prepare answers" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Research the job; prepare examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW.M9_JI_VAGUE', 'ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW', 'Answers vaguely with no example.', '{"question":"Why should we hire you?","wrong_answer":"I am good.","correct_answer":"I ran our school''s savings club and kept the records."}'::jsonb, 'Examples are not given.', 'Offer "I am good." beside "I ran our school''s savings club and kept the records." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Give an example that proves it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW.M9_JI_BAD_QUESTIONS', 'ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW', 'Asks the interviewee unfair or personal questions.', '{"question":"As interviewer, which is appropriate?","wrong_answer":"Which tribe are you?","correct_answer":"What skills would you bring to the job?"}'::jsonb, 'Fair interview questions are not taught.', 'Offer "Which tribe are you?" beside "What skills would you bring to the job?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask about skills and experience only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW.M9_JI_NO_CLOSE', 'ENGL.G9.LISTEN.T11_CONVERSATION_SKILLS_.JOB_INTERVIEW', 'Leaves without thanking the panel.', '{"question":"At the end you ...","wrong_answer":"leave","correct_answer":"thank the panel and say goodbye"}'::jsonb, 'Closing is forgotten.', 'Offer "leave" beside "thank the panel and say goodbye" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Thank them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION.M9_FN_REAL_PLACE', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION', 'Calls a story fiction only if its places are made up.', '{"question":"A made-up story set in Nairobi is ...","wrong_answer":"non-fiction","correct_answer":"fiction"}'::jsonb, 'Real places are taken as proof of fact.', 'Offer "non-fiction" beside "fiction" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fiction can use real places; the events are made up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION.M9_FN_BIOGRAPHY', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION', 'Calls a biography fiction because it tells a story.', '{"question":"A biography of Wangari Maathai is ...","wrong_answer":"fiction","correct_answer":"non-fiction"}'::jsonb, 'Narratives are all thought to be fiction.', 'Offer "fiction" beside "non-fiction" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'True life stories are non-fiction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION.M9_FN_COVER', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION', 'Decides by the cover picture.', '{"question":"How do you tell?","wrong_answer":"the cover","correct_answer":"the blurb, contents and whether events are real"}'::jsonb, 'Covers are the most visible.', 'Offer "the cover" beside "the blurb, contents and whether events are real" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the blurb and contents.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION.M9_FN_SCIENCE_FICTION', 'ENGL.G9.READIN.T11_EXTENSIVE_READING_FI.FICTION_NONFICTION', 'Calls science fiction non-fiction because it has science.', '{"question":"A story about robots on Mars is ...","wrong_answer":"non-fiction","correct_answer":"fiction"}'::jsonb, 'Science words suggest fact.', 'Offer "non-fiction" beside "fiction" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Made-up events, even with science, are fiction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED.M_EN9_NF_DECIDE', 'ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED', 'Gives the wrong noun for decide.', '{"question":"The noun from decide is...","wrong_answer":"decider","correct_answer":"decision"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "decider" next to the right answer and ask the question again in a new situation.', 'The noun from decide is decision.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED.M_EN9_NF_FRIEND', 'ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED', 'Gives the wrong noun for friend.', '{"question":"The noun formed from friend is...","wrong_answer":"friendly","correct_answer":"friendship"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "friendly" next to the right answer and ask the question again in a new situation.', 'Friendship is the noun formed from friend.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED.M_EN9_NF_CHILD', 'ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED', 'Gives the wrong noun for child.', '{"question":"The noun formed from child is...","wrong_answer":"childish","correct_answer":"childhood"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "childish" next to the right answer and ask the question again in a new situation.', 'Childhood is the noun formed from child.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED.M9_NF_ADJ_FOR_NOUN', 'ENGL.G9.GRAMMA.T11_WORD_CLASSES_NOUNS.NOUNS_FORMED', 'Uses an adjective where a noun is needed.', '{"question":"Her ___ surprised us. (kind)","wrong_answer":"kind","correct_answer":"kindness"}'::jsonb, 'The noun form is not formed.', 'Offer "kind" beside "kindness" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add -ness, -ity, -tion to make a noun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.PL_LESSONS.M_EN9_PL_LESSONS_DETAIL', 'ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.PL_LESSONS', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
