INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.PL_LESSONS.M9_PL_LESSON_PLOT', 'ENGL.G9.READIN.T11_GRADE_APPROPRIATE_PL.PL_LESSONS', 'Gives a plot event as the lesson.', '{"question":"Lesson of the play?","wrong_answer":"the son ran away","correct_answer":"listen to your parents'' advice"}'::jsonb, 'Events and lessons are confused.', 'Offer "the son ran away" beside "listen to your parents'' advice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A lesson is advice for life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.ABBREVIATIONS.M_EN9_AB_EG', 'ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.ABBREVIATIONS', 'Mixes e.g. and i.e.', '{"question":"What does e.g. mean?","wrong_answer":"that is","correct_answer":"for example"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "that is" next to the right answer and ask the question again in a new situation.', 'e.g. means for example.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
