INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.ABBREVIATIONS.M9_AB_FULL_STOPS', 'ENGL.G9.WRITIN.T11_MECHANICS_OF_WRITING.ABBREVIATIONS', 'Adds full stops inside acronyms said as words.', '{"question":"Write the acronym for the National Hospital Insurance Fund.","wrong_answer":"N.H.I.F.","correct_answer":"NHIF"}'::jsonb, 'Older full-stop rules are copied.', 'Offer "N.H.I.F." beside "NHIF" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Modern acronyms usually have no full stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
