INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M9_DW_NO_REVISION', 'ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Skips revising the dialogue.', '{"question":"After the draft?","wrong_answer":"publish","correct_answer":"revise for purpose and flow"}'::jsonb, 'Dialogues seem simple.', 'Offer "publish" beside "revise for purpose and flow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Revise and edit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M9_DW_DIRECTIONS', 'ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Writes directions as speech.', '{"question":"Wairimu smiles.","wrong_answer":"Wairimu: smiles","correct_answer":"Wairimu: (smiling) ..."}'::jsonb, 'Directions not separated.', 'Offer "Wairimu: smiles" beside "Wairimu: (smiling) ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Brackets.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING.M9_DW_NO_PURPOSE', 'ENGL.G9.WRITIN.T12_THE_WRITING_PROCESS_.DIALOGUE_WRITING', 'Writes a dialogue that goes nowhere.', '{"question":"A dialogue on grooming should ...","wrong_answer":"greet only","correct_answer":"show a view being shared or changed"}'::jsonb, 'Purpose not planned.', 'Offer "greet only" beside "show a view being shared or changed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan what changes by the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES.M_EN9_RS_IMAGES_DETAIL', 'ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES.M_EN9_RS_IMAGES_OPPOSITE', 'ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES.M_EN9_RS_IMAGES_NOTSAID', 'ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES', 'Picks something the text does not say.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is something not in the text" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must be found in the text, not added from outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES.M9_RS_IMAGES_ADD', 'ENGL.G9.READIN.T13_INTENSIVE_READING_VI.RS_IMAGES', 'Adds details to the image that are not in the text.', '{"question":"\"Waves slapped the old boat.\" Which detail is in the text?","wrong_answer":"a storm with lightning","correct_answer":"waves hitting an old boat"}'::jsonb, 'Imagination adds detail.', 'Offer "a storm with lightning" beside "waves hitting an old boat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use only the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING.M_EN9_SC_ALTHOUGH', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING', 'Uses because for contrast.', '{"question":"We played ___ it rained.","wrong_answer":"because","correct_answer":"although"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "because" next to the right answer and ask the question again in a new situation.', 'Although shows contrast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING.M_EN9_SC_BECAUSE', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING', 'Uses although for reason.', '{"question":"He was late ___ he missed the bus.","wrong_answer":"although","correct_answer":"because"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "although" next to the right answer and ask the question again in a new situation.', 'Because shows a reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING.M_EN9_SC_UNLESS', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING', 'Uses if for unless.', '{"question":"___ you study, you will fail.","wrong_answer":"If","correct_answer":"Unless"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "If" next to the right answer and ask the question again in a new situation.', 'Unless means if not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING.M9_SC_FRAGMENT', 'ENGL.G9.GRAMMA.T13_SENTENCES_COMPLEX_SE.SUBORDINATING', 'Writes the subordinate clause as a sentence on its own.', '{"question":"Is \"Because the ship was late.\" a sentence?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'A capital and full stop make it look complete.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Join it to a main clause: We waited because the ship was late.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS.M9_ID_LITERAL', 'ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS', 'Reads the idiom literally.', '{"question":"\"After the news, he was all at sea.\" Meaning?","wrong_answer":"he was on a ship","correct_answer":"he was confused"}'::jsonb, 'Literal reading.', 'Offer "he was on a ship" beside "he was confused" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use the context.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS.M9_ID_OPPOSITE', 'ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS', 'Gives the opposite meaning.', '{"question":"\"The trip was plain sailing.\" It was ...","wrong_answer":"difficult","correct_answer":"easy"}'::jsonb, 'Meaning is guessed.', 'Offer "difficult" beside "easy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the context.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS.M9_ID_WRONG_FIT', 'ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS', 'Chooses an idiom that does not fit.', '{"question":"Someone causes trouble in a calm meeting.","wrong_answer":"plain sailing","correct_answer":"rock the boat"}'::jsonb, 'Idioms known by form.', 'Offer "plain sailing" beside "rock the boat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Match the meaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS.M9_ID_CHANGED', 'ENGL.G9.WRITIN.T13_CREATIVE_WRITING_IDI.IDIOMS', 'Changes a word in the idiom.', '{"question":"Finish: to rock the ___","wrong_answer":"ship","correct_answer":"boat"}'::jsonb, 'Fixed form not learnt.', 'Offer "ship" beside "boat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Idioms are fixed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS.M9_QT_SAME_SIGN', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS', 'Uses the same sign in the tag.', '{"question":"You play football, ___?","wrong_answer":"do you","correct_answer":"don''t you"}'::jsonb, 'The tag is copied, not flipped.', 'Offer "do you" beside "don''t you" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Positive sentence, negative tag.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS.M9_QT_ISNT_IT', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS', 'Uses isn''t it for every tag.', '{"question":"They were late, ___?","wrong_answer":"isn''t it","correct_answer":"weren''t they"}'::jsonb, 'A fixed tag from Kenyan speech (isn''t it?).', 'Offer "isn''t it" beside "weren''t they" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Copy the helper and use a pronoun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS.M9_QT_LETS', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS', 'Uses the wrong tag after let''s.', '{"question":"Let''s go to the stadium, ___?","wrong_answer":"won''t we","correct_answer":"shall we"}'::jsonb, 'The special rule is not known.', 'Offer "won''t we" beside "shall we" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Let''s takes shall we.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS.M9_QT_TUNE', 'ENGL.G9.LISTEN.T14_INTONATION_IN_SENTEN.QUESTION_TAGS', 'Uses a rising tune when sure.', '{"question":"You are sure: \"It was a great match, wasn''t it?\"","wrong_answer":"rising","correct_answer":"falling"}'::jsonb, 'All tags are said as questions.', 'Offer "rising" beside "falling" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fall when you expect agreement.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY.M_EN9_RS_SUMMARY_DETAIL', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY.M_EN9_RS_SUMMARY_OPPOSITE', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY.M_EN9_RS_SUMMARY_NOTSAID', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY', 'Picks something the text does not say.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is something not in the text" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must be found in the text, not added from outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY.M9_RS_SUMMARY_OWN_WORDS', 'ENGL.G9.READIN.T14_SUMMARISING_ARGUMENT.RS_SUMMARY', 'Copies sentences instead of using own words.', '{"question":"Is a summary of copied sentences acceptable?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Copying feels safe.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Rewrite the points in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT.M_EN9_DI_QUOTE', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT', 'Keeps quotation marks in indirect speech.', '{"question":"Which is indirect speech?","wrong_answer":"She said, \"I am ill.\"","correct_answer":"She said that she was ill."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She said, "I am ill."" next to the right answer and ask the question again in a new situation.', 'Indirect speech has no quotation marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT.M_EN9_DI_TENSE', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT', 'Does not change the tense.', '{"question":"She said, \"I am ill.\" In indirect speech:","wrong_answer":"She said that she is ill.","correct_answer":"She said that she was ill."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "She said that she is ill." next to the right answer and ask the question again in a new situation.', 'Am becomes was.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT.M_EN9_DI_PRONOUN', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT', 'Does not change the pronoun.', '{"question":"He said, \"I like tea.\" In indirect speech:","wrong_answer":"He said that I liked tea.","correct_answer":"He said that he liked tea."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "He said that I liked tea." next to the right answer and ask the question again in a new situation.', 'I becomes he.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT.M9_DI_TIME_WORDS', 'ENGL.G9.GRAMMA.T14_SENTENCES_DIRECT_AND.DIRECT_INDIRECT', 'Keeps time words unchanged in indirect speech.', '{"question":"She said, \"I will come tomorrow.\" Indirect?","wrong_answer":"She said she would come tomorrow.","correct_answer":"She said she would come the next day."}'::jsonb, 'Only tense and pronoun are changed.', 'Offer "She said she would come tomorrow." beside "She said she would come the next day." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Change time words too: tomorrow becomes the next day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M9_DC_FEW_SENSES', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Uses only sight.', '{"question":"Use all five senses for the stadium.","wrong_answer":"only sights","correct_answer":"sights, sounds, smells, touch and taste"}'::jsonb, 'Sight comes first.', 'Offer "only sights" beside "sights, sounds, smells, touch and taste" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Plan a line for each sense.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M9_DC_NARRATES', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Narrates instead of describing.', '{"question":"Describe the World Cup final.","wrong_answer":"First they kicked off, then they scored.","correct_answer":"The stadium throbbed with drums and blazing colour."}'::jsonb, 'Narrative is most practised.', 'Offer "First they kicked off, then they scored." beside "The stadium throbbed with drums and blazing colour." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Describe what it is like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M9_DC_LENGTH', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Writes far from 280 to 320 words.', '{"question":"Is 150 words enough?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Word count ignored.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Add senses and details.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION.M9_DC_SPELLING', 'ENGL.G9.WRITIN.T14_DESCRIPTIVE_WRITING_.DESCRIPTIVE_COMPOSITION', 'Leaves spelling errors uncorrected.', '{"question":"After drafting?","wrong_answer":"hand it in","correct_answer":"edit for spelling"}'::jsonb, 'Editing is skipped.', 'Offer "hand it in" beside "edit for spelling" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Edit before the final copy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT.M9_NR_OPINION', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT', 'Adds opinions to a news report.', '{"question":"Which suits a news report?","wrong_answer":"The terrible, useless council failed again.","correct_answer":"The council has delayed the road repairs."}'::jsonb, 'News is confused with comment.', 'Offer "The terrible, useless council failed again." beside "The council has delayed the road repairs." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Report facts in a neutral tone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT.M9_NR_TIME', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT', 'Reads too slowly or too fast for the time given.', '{"question":"You have two minutes for the report.","wrong_answer":"finishes in thirty seconds","correct_answer":"about two minutes at a steady pace"}'::jsonb, 'Timing is not practised.', 'Offer "finishes in thirty seconds" beside "about two minutes at a steady pace" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Practise with a timer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT.M9_NR_NO_HEADLINE', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT', 'Buries the main news at the end.', '{"question":"What comes first in a news report?","wrong_answer":"background","correct_answer":"the main news (headline)"}'::jsonb, 'Stories are told in time order.', 'Offer "background" beside "the main news (headline)" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lead with the main news.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT.M9_NR_MISSING_WS', 'ENGL.G9.LISTEN.T15_ORAL_REPORTS_NEWS_RO.NEWS_REPORT', 'Leaves out who, where or when.', '{"question":"What is missing: \"A ship sank.\"?","wrong_answer":"nothing","correct_answer":"where and when, and who was affected"}'::jsonb, 'The reporter knows the details.', 'Offer "nothing" beside "where and when, and who was affected" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check who, what, where, when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY.M_EN9_RS_FLUENCY_DETAIL', 'ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY', 'Picks one small detail instead of the answer asked for.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is a small detail","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is a small detail" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must cover what the question asks, not one small detail.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY.M_EN9_RS_FLUENCY_OPPOSITE', 'ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY', 'Picks the opposite of what the text says.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is the opposite","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is the opposite" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must agree with the text, not say the opposite.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY.M_EN9_RS_FLUENCY_NOTSAID', 'ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY', 'Picks something the text does not say.', '{"question":"Which answer fits the text?","wrong_answer":"an answer that is something not in the text","correct_answer":"the answer the text supports"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "an answer that is something not in the text" next to the right answer and ask the question again in a new situation.', 'Check the answer against the text: it must be found in the text, not added from outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN.M9_SK_READ_ALL', 'ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN', 'Reads every word to find one fact.', '{"question":"Find the date of the World Cup final.","wrong_answer":"read the whole article","correct_answer":"scan for numbers and \"final\""}'::jsonb, 'One reading habit.', 'Offer "read the whole article" beside "scan for numbers and "final"" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Scan for the key word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN.M9_SK_GIST_DETAIL', 'ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN', 'Gives a detail as the gist.', '{"question":"Skim: what is the text about?","wrong_answer":"Messi scored twice","correct_answer":"the history of the World Cup"}'::jsonb, 'A detail catches the eye.', 'Offer "Messi scored twice" beside "the history of the World Cup" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Gist is the whole topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN.M9_SK_STOP_UNKNOWN', 'ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN', 'Stops previewing at unknown words.', '{"question":"You meet unknown words while previewing.","wrong_answer":"stop","correct_answer":"ignore them and read on"}'::jsonb, 'Every word is thought necessary.', 'Offer "stop" beside "ignore them and read on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Previewing skips unknown words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN.M9_SK_WRONG_KEYWORD', 'ENGL.G9.READIN.T15_READING_FLUENCY.SKIM_SCAN', 'Scans for the wrong key word.', '{"question":"Find the stadium''s capacity.","wrong_answer":"scans for \"stadium\" only","correct_answer":"scans for numbers near \"capacity\" or \"seats\""}'::jsonb, 'The key word is not thought through.', 'Offer "scans for "stadium" only" beside "scans for numbers near "capacity" or "seats"" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Choose the word the answer will be near.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY.M9_RS_FLUENCY_TITLE', 'ENGL.G9.READIN.T15_READING_FLUENCY.RS_FLUENCY', 'Predicts without using the title.', '{"question":"Title: \"The Last Voyage\". Predict.","wrong_answer":"a football match","correct_answer":"a final journey by sea"}'::jsonb, 'Titles are skipped.', 'Offer "a football match" beside "a final journey by sea" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with the title.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE.M_EN9_EI_MARK', 'ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE', 'Ends an exclamation with a question mark.', '{"question":"Which is punctuated correctly?","wrong_answer":"What a lovely day?","correct_answer":"What a lovely day!"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "What a lovely day?" next to the right answer and ask the question again in a new situation.', 'An exclamation ends with an exclamation mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE.M_EN9_EI_COMMAND', 'ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE', 'Calls a command a question.', '{"question":"Which is an imperative?","wrong_answer":"Are you coming?","correct_answer":"Close the door."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Are you coming?" next to the right answer and ask the question again in a new situation.', 'An imperative gives a command.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE.M_EN9_EI_STOP', 'ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE', 'Ends a command with a question mark.', '{"question":"Which is punctuated correctly?","wrong_answer":"Sit down?","correct_answer":"Sit down."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Sit down?" next to the right answer and ask the question again in a new situation.', 'A command ends with a full stop or exclamation mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE.M9_EI_POLITE_IMPERATIVE', 'ENGL.G9.GRAMMA.T15_SENTENCES_1_IMPERATI.EXCLAM_IMPERATIVE', 'Ends a polite request with an exclamation mark.', '{"question":"Please pass the salt___","wrong_answer":"!","correct_answer":"."}'::jsonb, 'All imperatives are thought to need !', 'Offer "!" beside "." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A calm request ends with a full stop.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T15_EMAILS.EMAIL.M9_EM_NO_SUBJECT', 'ENGL.G9.WRITIN.T15_EMAILS.EMAIL', 'Leaves the subject line empty.', '{"question":"What goes in the subject line?","wrong_answer":"nothing","correct_answer":"a short summary: Trip to Mombasa, 12 May"}'::jsonb, 'The subject seems optional.', 'Offer "nothing" beside "a short summary: Trip to Mombasa, 12 May" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Always write a clear subject.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T15_EMAILS.EMAIL.M9_EM_TEXTSPEAK', 'ENGL.G9.WRITIN.T15_EMAILS.EMAIL', 'Writes a formal email in text-speak.', '{"question":"Email to a tour company?","wrong_answer":"hi, wnt 2 book trip","correct_answer":"Good morning. I would like to book a trip."}'::jsonb, 'Phone habits.', 'Offer "hi, wnt 2 book trip" beside "Good morning. I would like to book a trip." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Write in full for formal emails.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T15_EMAILS.EMAIL.M9_EM_LETTER_ADDRESSES', 'ENGL.G9.WRITIN.T15_EMAILS.EMAIL', 'Adds postal addresses as in a letter.', '{"question":"Does an email need the postal address at the top?","wrong_answer":"Yes","correct_answer":"No"}'::jsonb, 'Letter format carried over.', 'Offer "Yes" beside "No" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The email address does that job.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G9.WRITIN.T15_EMAILS.EMAIL.M9_EM_FORGOT_ATTACHMENT', 'ENGL.G9.WRITIN.T15_EMAILS.EMAIL', 'Mentions an attachment and forgets to attach it.', '{"question":"Your email says \"attached is my form\". Before sending?","wrong_answer":"send","correct_answer":"check the file is attached"}'::jsonb, 'Attachments are forgotten.', 'Offer "send" beside "check the file is attached" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Attach, then send.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
